model Ticket {
  id        String          @id @default(cuid())
  subject   String
  status    TicketStatus    @default(OPEN)
  priority  TicketPriority  @default(NORMAL)
  userId    String
  user      User            @relation(fields: [userId], references: [id], onDelete: Cascade)
  messages  TicketMessage[]
  createdAt DateTime        @default(now())
  updatedAt DateTime        @updatedAt

  // Discord support bridge (lib/discord-bridge.ts): the id of the private-guild
  // text channel mirroring this ticket, so a re-opened/replied ticket posts into
  // the SAME channel instead of creating a new one each time. Null until the
  // bridge first mirrors this ticket (or always null while discord_enabled is
  // off / the bridge fails — best-effort, never blocks ticket creation).
  //
  // NOT YET PUSHED to the live database — this worktree deliberately did not
  // run `prisma db push` (or regenerate the shared Prisma Client, which is
  // symlinked into the live /opt/nxeon node_modules) against the real, shared
  // Postgres instance, to avoid the running production app requesting a column
  // that does not exist yet. Run `npx prisma db push` (then `npx prisma
  // generate`) for real once this branch is reviewed and ready to promote —
  // see lib/discord-bridge.ts, which reads/writes this field via an explicit
  // unchecked cast until then.
  discordThreadId String?
}

model TicketMessage {
  id        String   @id @default(cuid())
  body      String
  isStaff   Boolean  @default(false)
  ticketId  String
  ticket    Ticket   @relation(fields: [ticketId], references: [id], onDelete: Cascade)
  authorId  String
  author    User     @relation(fields: [authorId], references: [id], onDelete: Cascade)
  createdAt DateTime @default(now())

  // Read receipt — staff -> customer visibility ONLY, never the reverse. Stamped
  // by app/dashboard/support/[id]/page.tsx when a customer views a ticket with
  // unread staff messages (isStaff: true, readAt: null). Rendered as a
  // read/delivered indicator on the ADMIN side only (components/admin/*) — the
  // customer UI never shows a receipt, on themselves or on staff messages they
  // just read. Null until read.
  readAt DateTime?

  // Edit window: `editTicketMessage` (lib/actions-support.ts) lets the original
  // author edit within 5 minutes of `createdAt`, enforced server-side. Unlike
  // `readAt` above, this IS shown to both parties — an edit is a transparency
  // signal, not a privacy one. Null until edited.
  editedAt DateTime?

  // One attachment per message (image or a small set of common document types),
  // bytes stored in Postgres exactly like ChatAttachment/lib/chat-attachment.ts —
  // see lib/ticket-attachment.ts for the validator. All four are null together
  // when the message carries no attachment.
  attachmentData Bytes?
  attachmentMime String?
  attachmentName String?
  attachmentSize Int?
}

model ChatConversation {
  id             String        @id @default(cuid())
  userId         String? // set if the visitor is a signed-in customer
  visitorId      String // anonymous client id (cookie/localStorage)
  name           String?
  email          String?
  status         String        @default("OPEN") // OPEN | CLOSED
  assignedToId   String? // staff user id handling it
  unreadForAgent Boolean       @default(true)
  unreadForUser  Boolean       @default(false)
  lastMessageAt  DateTime      @default(now())
  createdAt      DateTime      @default(now())
  // AI-assistant human-handoff window: set (atomically) when the bot escalates
  // to a live agent and emails them. While set, the bot stays quiet waiting for
  // a human; if the window elapses with no agent, the bot posts the "no agents
  // available" fallback and clears this back to null (so a later ask can retry).
  botEscalatedAt DateTime?
  // Per-conversation kill switch for the AI assistant, set by staff from the
  // admin inbox (lib/actions-chat.ts's `toggleAiPaused`). While true,
  // lib/kb-run.ts's `runAssistant` returns immediately without posting a bot
  // reply — the visitor's message is still saved and flagged unread for a
  // human exactly as it always is (see POST /api/chat), so pausing the bot
  // never hides a message, it just stops the AI from answering it.
  aiPaused       Boolean       @default(false)
  messages       ChatMessage[]

  // Discord support bridge (lib/discord-bridge.ts): same purpose and same
  // "not yet pushed" caveat as Ticket.discordThreadId above — see that field's
  // doc comment for the full explanation. Read/written via an explicit
  // unchecked cast in lib/discord-bridge.ts until a real `prisma db push` +
  // `generate` runs for this branch.
  discordThreadId String?

  @@index([status, lastMessageAt])
  @@index([visitorId])
}

model ChatMessage {
  id             String           @id @default(cuid())
  conversationId String
  conversation   ChatConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)
  sender         String // "visitor" | "agent"
  body           String // may be "" for an image-only message
  // Rich UI attached to a bot message (Kodee-style plan cards etc.) — a JSON
  // array of PlanCard, resolved server-side from real catalog data so the model
  // only ever picks card keys. Null for plain messages.
  cardsJson      String?
  createdAt      DateTime         @default(now())
  attachment     ChatAttachment?

  @@index([conversationId, createdAt])
}

model ChatAttachment {
  id        String      @id @default(cuid())
  messageId String      @unique
  message   ChatMessage @relation(fields: [messageId], references: [id], onDelete: Cascade)
  mime      String
  sizeBytes Int
  data      Bytes
  createdAt DateTime    @default(now())
}

model Feedback {
  id        String   @id @default(cuid())
  userId    String?
  user      User?    @relation(fields: [userId], references: [id], onDelete: SetNull)
  kind      String // BUG | FEATURE
  title     String
  body      String
  url       String? // page the reporter was on
  status    String   @default("NEW") // NEW | PLANNED | IN_PROGRESS | DONE | DECLINED
  adminNote String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
}

model AuditLog {
  id        String   @id @default(cuid())
  userId    String?
  user      User?    @relation(fields: [userId], references: [id])
  action    String
  detail    String?
  createdAt DateTime @default(now())
}

model Notification {
  id        String    @id @default(cuid())
  title     String
  body      String?
  href      String?
  readAt    DateTime?
  userId    String
  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)
  createdAt DateTime  @default(now())
}

model Announcement {
  id         String                  @id @default(cuid())
  title      String
  body       String?
  level      String                  @default("INFO") // INFO | SUCCESS | WARNING | CRITICAL
  active     Boolean                 @default(true)
  startsAt   DateTime? // optional scheduled start; hidden to customers until then
  expiresAt  DateTime? // optional auto-hide (end of window)
  createdBy  String? // admin user id (audit only)
  createdAt  DateTime                @default(now())
  updatedAt  DateTime                @default(now()) @updatedAt
  dismissals AnnouncementDismissal[]
}

model AnnouncementDismissal {
  id             String       @id @default(cuid())
  announcementId String
  announcement   Announcement @relation(fields: [announcementId], references: [id], onDelete: Cascade)
  userId         String
  createdAt      DateTime     @default(now())

  @@unique([announcementId, userId])
  @@index([userId])
}

model UpdateAnnouncement {
  id           String    @id @default(cuid())
  title        String
  body         String    // Markdown
  serviceTypes String[]  // e.g. ["GAME","VPS","HOSTING"] — empty = all services
  gameFamilies String[]  // e.g. ["minecraft","rust"] — which games this update covers (GAME-scoped only; empty = not game-specific)
  screenshotUrl String?  // relative path to an uploaded screenshot
  status       String    @default("DRAFT") // DRAFT | PUBLISHED
  publishedAt  DateTime?
  createdAt    DateTime  @default(now())
  updatedAt    DateTime  @updatedAt
  seenBy       UserAnnouncementSeen[]

  @@index([status, publishedAt])
}

model UserAnnouncementSeen {
  id             String   @id @default(cuid())
  userId         String
  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)
  announcementId String
  announcement   UpdateAnnouncement @relation(fields: [announcementId], references: [id], onDelete: Cascade)
  seenAt         DateTime @default(now())

  @@unique([userId, announcementId])
  @@index([userId])
}

model StatusIncident {
  id         String    @id @default(cuid())
  component  String? // affected component, or null for platform-wide
  severity   String    @default("degraded") // degraded | down | maintenance
  title      String
  body       String    @default("")
  startedAt  DateTime  @default(now())
  resolvedAt DateTime?
  auto       Boolean   @default(false) // opened automatically vs by an operator
  createdAt  DateTime  @default(now())
  updatedAt  DateTime  @updatedAt

  @@index([startedAt])
  @@index([resolvedAt])
}

model HealthSample {
  id        String   @id @default(cuid())
  component String // web | proxmox | worker | db
  status    String // operational | degraded | down
  latencyMs Int?
  detail    String?
  ts        DateTime @default(now())

  @@index([component, ts])
  @@index([ts])
}

model KbChunk {
  id        String   @id @default(cuid())
  source    String // "faq" | "blog"
  refId     String // faq-<n> | blog slug — provenance only
  title     String
  url       String? // where to read more (relative path or absolute URL)
  content   String // searchable text (title + body); indexed via to_tsvector
  snippet   String // short display text the assistant actually sends
  category  String? // FAQ grouping, for admin/coverage views
  offer     Boolean  @default(false) // append the current promo nudge to this answer
  updatedAt DateTime @default(now())

  @@index([source])
}

model KbBotLog {
  id             String   @id @default(cuid())
  visitorId      String?
  conversationId String?
  question       String
  kind           String // smalltalk | handoff | offer | answer | none
  matchedTitle   String?
  createdAt      DateTime @default(now())

  @@index([createdAt])
  @@index([kind, createdAt])
}

model KbSuggestion {
  id        String   @id @default(cuid())
  question  String
  answer    String // proposed FAQ-style answer
  category  String?
  source    String   @default("gap") // gap | conversation
  status    String   @default("pending") // pending | approved | rejected
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([status, createdAt])
}

model EmailLog {
  id        String   @id @default(cuid())
  toEmail   String
  subject   String
  template  String? // template key (welcome, receipt, ...)
  html      String // rendered HTML, secrets redacted — see the model comment
  status    String   @default("SENT") // SENT | FAILED
  error     String?
  userId    String?
  createdAt DateTime @default(now())
  // Open/click tracking. `html` above already carries the tracking pixel +
  // rewritten link URLs (lib/mailer.ts sendMail), and the pixel/redirect routes
  // under app/api/track/email/[id]/... update these fields as events arrive.
  openedAt   DateTime?
  openCount  Int       @default(0)
  clickedAt  DateTime?
  clickCount Int       @default(0)
  // Real destination URLs, indexed positionally — app/api/track/email/[id]/
  // click/[idx] looks one up here to redirect. Anchors whose original href
  // carried a bearer secret (token/code/key/…, see SECRET_QUERY_PARAM in
  // lib/email-render.ts) are deliberately excluded from both this array AND
  // click-rewriting entirely: the whole point of that redaction is that a
  // secret must never gain a second, more casually-queryable home, and this
  // column — read by a plain unauthenticated GET — would be exactly that.
  links      Json?
  // Retry classification (see lib/critical-email-retry.ts, worker/critical-
  // email-retry.ts). `kind` mirrors the `NotifyKind` (lib/prefs.ts) passed to
  // `sendMail()`, if any — this is what lets the retry sweep find a FAILED row
  // whose kind is CRITICAL (payment_failed, provision_ready, suspension, ...)
  // without re-deriving the original template context. Null for sends that
  // omitted `kind` (most PRODUCT/no-preference sends) and for any row written
  // before this column existed.
  kind String?
  // Count of automatic resend attempts the retry sweep has made against THIS
  // row. Bounded by MAX_RETRIES_PER_EMAIL. A resend attempt itself writes its
  // OWN EmailLog row (like any other send), but that new row is written
  // without `kind` — see the sweep's doc comment — so it can never become a
  // fresh retry root; this counter is what actually bounds the whole chain.
  retryCount Int @default(0)
}

model EmailTemplate {
  id        String   @id @default(cuid())
  key       String   @unique // welcome, receipt, server_provisioned, ...
  name      String
  category  String   @default("Account") // Account | Billing | Servers | Domains | Support | Security
  subject   String
  html      String // body with {{variable}} placeholders
  enabled   Boolean  @default(true)
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
}

model CannedReply {
  id          String   @id @default(cuid())
  title       String
  body        String
  createdById String
  createdBy   User     @relation(fields: [createdById], references: [id])
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt
}

=== ENUMS ===
enum TicketStatus {
  OPEN
  ANSWERED
  CUSTOMER_REPLY
  CLOSED
}

enum TicketPriority {
  LOW
  NORMAL
  HIGH
  URGENT
}

import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { StatusDot, Badge, EmptyState, timeAgo } from "@/components/ui/primitives";
import { PortalHero } from "@/components/portal/PortalHero";
import { NewTicketForm } from "@/components/customer/TicketForms";
import { SUPPORT_REPLY_SENTENCE, SUPPORT_REPLY_WITHIN } from "@/lib/support-promise";

export const dynamic = "force-dynamic";

const priorityTone: Record<string, "slate" | "brand" | "amber" | "red"> = {
  LOW: "slate",
  NORMAL: "brand",
  HIGH: "amber",
  URGENT: "red",
};

export default async function SupportPage() {
  const user = await requireUser();
  const tickets = await db.ticket.findMany({
    where: { userId: user.id },
    include: { _count: { select: { messages: true } } },
    orderBy: { updatedAt: "desc" },
  });

  return (
    <div className="space-y-6">
      {/* One shared reply promise site-wide — this page used to say "a few hours"
          while /contact said one business day and the chat widget said minutes. */}
      <PortalHero variant="support" title="Support" sub={SUPPORT_REPLY_SENTENCE} />
      <div className="-mt-3"><Link href="/dashboard/feedback" className="text-sm text-brand-300 hover:underline">Have a product idea or bug? Send feedback →</Link></div>

      <NewTicketForm />

      {tickets.length === 0 ? (
        <EmptyState
          title="No tickets yet"
          sub={`Hit a snag or have a question? Open a ticket and a human will get back to you ${SUPPORT_REPLY_WITHIN}.`}
        />
      ) : (
        <div className="card overflow-x-auto p-0">
          <table className="table-shell min-w-[600px]">
            <thead>
              <tr>
                <th>Subject</th>
                <th>Status</th>
                <th>Priority</th>
                <th>Messages</th>
                <th className="text-right">Updated</th>
              </tr>
            </thead>
            <tbody>
              {tickets.map((t) => (
                <tr key={t.id}>
                  <td>
                    <Link
                      href={`/dashboard/support/${t.id}`}
                      className="font-semibold text-slate-100 hover:text-brand-300"
                    >
                      {t.subject}
                    </Link>
                  </td>
                  <td>
                    <StatusDot status={t.status} />
                  </td>
                  <td>
                    <Badge tone={priorityTone[t.priority] ?? "slate"}>
                      {t.priority.toLowerCase()}
                    </Badge>
                  </td>
                  <td className="text-slate-400">{t._count.messages}</td>
                  <td className="text-right text-slate-400">{timeAgo(t.updatedAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
import { notFound } from "next/navigation";
import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { PageHeader, StatusDot, Badge, timeAgo } from "@/components/ui/primitives";
import { ReplyForm, TicketStatusButton } from "@/components/customer/TicketForms";
import { markTicketMessagesRead } from "@/lib/actions-support";
import { MessageAttachment } from "@/components/support/MessageAttachment";
import { EditableMessageBody } from "@/components/support/EditableMessageBody";

export const dynamic = "force-dynamic";

const priorityTone: Record<string, "slate" | "brand" | "amber" | "red"> = {
  LOW: "slate",
  NORMAL: "brand",
  HIGH: "amber",
  URGENT: "red",
};

export default async function TicketPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const user = await requireUser();
  const ticket = await db.ticket.findUnique({
    where: { id },
    include: {
      messages: {
        select: {
          id: true,
          body: true,
          isStaff: true,
          authorId: true,
          createdAt: true,
          editedAt: true,
          attachmentMime: true,
          attachmentName: true,
          attachmentSize: true,
          author: true,
        },
        orderBy: { createdAt: "asc" },
      },
    },
  });
  if (!ticket || (ticket.userId !== user.id && user.role !== "ADMIN")) notFound();

  // Read receipts flow staff -> customer only ("read receipts from customers,
  // but they dont get them from us"): viewing the ticket as its owning customer
  // stamps `readAt` on every unread staff message, but this page never RENDERS
  // any receipt itself — that indicator only ever appears on the admin thread.
  // A no-op for anyone but the ticket's own customer (including an admin
  // viewing here as themselves, not impersonating).
  await markTicketMessagesRead(ticket.id);

  return (
    <div className="space-y-6">
      <PageHeader title={ticket.subject} sub={`Opened ${timeAgo(ticket.createdAt)}`}>
        <Link href="/dashboard/support" className="btn-ghost">
          ← All tickets
        </Link>
        <TicketStatusButton ticketId={ticket.id} status={ticket.status} />
      </PageHeader>

      <div className="flex items-center gap-3">
        <StatusDot status={ticket.status} />
        <Badge tone={priorityTone[ticket.priority] ?? "slate"}>{ticket.priority.toLowerCase()}</Badge>
      </div>

      <div className="space-y-4">
        {ticket.messages.map((m) => (
          <div key={m.id} className={`flex ${m.isStaff ? "justify-start" : "justify-end"}`}>
            <div
              className={`max-w-[85%] rounded-2xl px-4 py-3 sm:max-w-[70%] ${
                m.isStaff
                  ? "glass rounded-tl-sm"
                  : "rounded-tr-sm bg-gradient-to-br from-accent-blue/30 to-brand-500/30 ring-1 ring-brand-500/30"
              }`}
            >
              <div className="mb-1 flex items-baseline justify-between gap-4">
                <span className={`text-xs font-semibold ${m.isStaff ? "text-brand-300" : "text-slate-200"}`}>
                  {m.isStaff ? `${m.author.name} · Nxeon staff` : m.author.name}
                </span>
                <span className="text-[11px] text-slate-500">{timeAgo(m.createdAt)}</span>
              </div>
              <EditableMessageBody
                messageId={m.id}
                initialBody={m.body}
                createdAtIso={m.createdAt.toISOString()}
                editedAtIso={m.editedAt?.toISOString() ?? null}
                canEditPermission={m.authorId === user.id && ticket.status !== "CLOSED"}
                bodyClassName="whitespace-pre-wrap text-sm text-slate-100"
              />
              {m.attachmentMime && m.attachmentName && (
                <MessageAttachment
                  messageId={m.id}
                  mime={m.attachmentMime}
                  name={m.attachmentName}
                  size={m.attachmentSize ?? 0}
                />
              )}
            </div>
          </div>
        ))}
      </div>

      {ticket.status === "CLOSED" ? (
        <div className="card text-center text-sm text-slate-400">
          This ticket is closed. Reopen it above to continue the conversation.
        </div>
      ) : (
        <div className="card">
          <p className="section-label mb-3">Reply</p>
          <ReplyForm ticketId={ticket.id} />
        </div>
      )}
    </div>
  );
}
"use client";

import { useActionState, useEffect, useRef, useState, useTransition } from "react";
import { createTicket, replyTicket, setTicketStatus } from "@/lib/actions-support";
import { ReplyComposer, type ReplyComposerHandle } from "@/components/support/ReplyComposer";

export function NewTicketForm() {
  const [open, setOpen] = useState(false);
  const [state, action, pending] = useActionState(createTicket, {});
  // CONTROLLED, deliberately. React 19 resets uncontrolled inputs on every
  // `<form action={fn}>` submit, so a rejected ticket came back with the subject
  // and the body — up to 10,000 characters — blank. The person retyping it is by
  // definition someone who already has a problem and has just been told "no".
  //
  // This is the same reset that permanently locked customers out of 2FA login
  // (see components/AuthForms.tsx). There the cost was the account; here it is
  // the customer's own words, which they will not write twice.
  const [subject, setSubject] = useState("");
  const [priority, setPriority] = useState("NORMAL");
  const [body, setBody] = useState("");

  return (
    <div>
      <div className="flex justify-end">
        <button className={open ? "btn-secondary" : "btn-primary"} onClick={() => setOpen((o) => !o)}>
          {open ? "Cancel" : "+ New ticket"}
        </button>
      </div>
      {open && (
        <form action={action} className="card mt-4 animate-fade-up space-y-4">
          {state?.error && (
            <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
              {state.error}
            </div>
          )}
          <div className="grid gap-4 sm:grid-cols-[1fr_180px]">
            <div>
              <label className="label">Subject</label>
              <input
                className="input"
                name="subject"
                required
                minLength={3}
                maxLength={150}
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
                placeholder="Briefly, what's going on?"
              />
            </div>
            <div>
              <label className="label">Priority</label>
              <select className="input" name="priority" value={priority} onChange={(e) => setPriority(e.target.value)}>
                <option value="LOW">Low</option>
                <option value="NORMAL">Normal</option>
                <option value="HIGH">High</option>
                <option value="URGENT">Urgent</option>
              </select>
            </div>
          </div>
          <div>
            <label className="label">Message</label>
            <textarea
              className="input min-h-32 resize-y"
              name="body"
              required
              minLength={5}
              maxLength={10000}
              value={body}
              onChange={(e) => setBody(e.target.value)}
              placeholder="Include the server hostname and any error messages — the more detail, the faster we can help."
            />
          </div>
          <div className="flex justify-end">
            <button className="btn-primary px-6" disabled={pending}>
              {pending ? "Opening…" : "Open ticket"}
            </button>
          </div>
        </form>
      )}
    </div>
  );
}

export function ReplyForm({ ticketId }: { ticketId: string }) {
  const [state, action, pending] = useActionState(replyTicket, {});
  const [body, setBody] = useState("");
  const composerRef = useRef<ReplyComposerHandle>(null);
  // A reply has two outcomes and they want OPPOSITE things from the field, which
  // is why simply making it controlled is not enough:
  //   - rejected  → keep every character; React 19 would otherwise blank up to
  //                 10,000 of them on the form-action submit, and the customer
  //                 will not retype them.
  //   - accepted  → clear it, or the sent reply sits there looking unsent and
  //                 gets sent twice.
  // So the field is controlled and cleared only on a submit that came back
  // without an error, watching the pending edge rather than the state shape
  // (the action returns `{}` for success, which is indistinguishable from its
  // initial value).
  const wasPending = useRef(false);
  useEffect(() => {
    if (wasPending.current && !pending && !state?.error) {
      setBody("");
      composerRef.current?.resetAttachment();
    }
    wasPending.current = pending;
  }, [pending, state]);
  return (
    <form action={action} className="space-y-3">
      <input type="hidden" name="ticketId" value={ticketId} />
      {state?.error && <p className="text-sm text-red-400">{state.error}</p>}
      <ReplyComposer
        ref={composerRef}
        value={body}
        onChange={setBody}
        placeholder="Write a reply…"
        disabled={pending}
      />
      <div className="flex justify-end">
        <button className="btn-primary px-6" disabled={pending}>
          {pending ? "Sending…" : "Send reply"}
        </button>
      </div>
    </form>
  );
}

export function TicketStatusButton({ ticketId, status }: { ticketId: string; status: string }) {
  const [pending, start] = useTransition();
  const closed = status === "CLOSED";
  return (
    <button
