const TICKET_PRIORITY_CHOICES = ["LOW", "NORMAL", "HIGH", "URGENT"] as const;

export async function setTicketStatus(ticketId: string, status: "OPEN" | "CLOSED") {
  const user = await requireTicketActor();
  if (!TICKET_STATUS_CHOICES.includes(status as (typeof TICKET_STATUS_CHOICES)[number])) {
    throw new Error("A ticket can only be reopened or closed from here.");
  }
  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
  if (!ticket) throw new Error("Not found");
  if (ticket.userId !== user.id && !user.isSupportStaff) throw new Error("Forbidden");
  await db.ticket.update({ where: { id: ticketId }, data: { status } });
