export async function setTicketPriority(ticketId: string, priority: "LOW" | "NORMAL" | "HIGH" | "URGENT") {
  const user = await requireTicketActor();
  // Triage is a staff-only judgement — a customer must not be able to promote
  // their own ticket to URGENT — but it IS the support desk's job.
  if (!user.isSupportStaff) throw new Error("Forbidden");
  if (!TICKET_PRIORITY_CHOICES.includes(priority as (typeof TICKET_PRIORITY_CHOICES)[number])) {
    throw new Error("Priority must be one of: LOW, NORMAL, HIGH, URGENT.");
  }
  await db.ticket.update({ where: { id: ticketId }, data: { priority } });
