  if (message.authorId !== user.id) return { error: "You can only edit your own messages." };
  if (message.ticket.status === "CLOSED") return { error: "This ticket is closed." };
  if (Date.now() - message.createdAt.getTime() >= EDIT_WINDOW_MS) {
    return { error: "You can only edit a message within 5 minutes of sending it." };
  }

  await db.ticketMessage.update({ where: { id: messageId }, data: { body, editedAt: new Date() } });
