/** Write a ticket reply. Mirrors `replyTicket`'s exact prior DB-write body. */
export async function writeTicketReply(args: {
  /** The id of the user the message is authored as (TicketMessage.authorId). */
  actorId: string;
  /** Whether the calling actor is support staff (before the same-ticket-owner override below). */
  actorIsSupportStaff: boolean;
  ticketId: string;
  body: string;
  /** Optional single attachment (image or document) — see lib/ticket-attachment.ts. */
  attachment?: { mime: string; name: string; size: number; data: Buffer };
}): Promise<{ error?: string; isStaff?: boolean; ticketUserId?: string; subject?: string }> {
  const body = args.body.trim();
  // A message with an attachment and no caption is allowed (mirrors the chat
  // widget's image-only messages), so the length floor only applies when there
  // is no attachment to carry the message on its own.
  if (!args.attachment && (body.length < 2 || body.length > 10000)) return { error: "Message too short." };
  if (body.length > 10000) return { error: "Message is too long." };

  const ticket = await db.ticket.findUnique({ where: { id: args.ticketId } });
  if (!ticket) return { error: "Ticket not found." };
  // A staff member replying to their OWN ticket (as its customer) is not a
  // "staff reply" — exactly the same override the original action applied.
  const isStaff = args.actorIsSupportStaff && ticket.userId !== args.actorId;
  if (ticket.userId !== args.actorId && !args.actorIsSupportStaff) return { error: "Forbidden." };

  await db.$transaction([
    db.ticketMessage.create({
      data: {
        ticketId: args.ticketId,
        body,
        authorId: args.actorId,
        isStaff,
        ...(args.attachment
          ? {
              attachmentData: new Uint8Array(args.attachment.data),
              attachmentMime: args.attachment.mime,
              attachmentName: args.attachment.name,
              attachmentSize: args.attachment.size,
            }
          : {}),
      },
    }),
    db.ticket.update({
      where: { id: args.ticketId },
      data: { status: isStaff ? "ANSWERED" : "CUSTOMER_REPLY" },
    }),
  ]);

  if (isStaff) {
    await db.notification.create({
      data: {
        userId: ticket.userId,
        title: `Support replied: ${ticket.subject}`,
        href: `/dashboard/support/${args.ticketId}`,
      },
    });
    // Also EMAIL the customer the staff reply — an in-app bell alone is easy to
    // miss. Best-effort: a mail failure must never fail the reply itself.
    // Rate-governed (coalesce window + daily cap) — see lib/ticket-reply-email.ts.
    try {
      await maybeSendTicketReplyEmail({
        ticketId: args.ticketId,
        ticketUserId: ticket.userId,
        ticketSubject: ticket.subject,
        replyBody: body,
      });
    } catch (e) {
      console.error("[support] staff-reply email failed (non-fatal)", e);
    }
  } else {
    const admins = await db.user.findMany({ where: { role: "ADMIN" } });
    await db.notification.createMany({
      data: admins.map((a) => ({
        userId: a.id,
        title: `Ticket reply: ${ticket.subject}`,
        href: `/admin/support/${args.ticketId}`,
      })),
    });
  }

  return { isStaff, ticketUserId: ticket.userId, subject: ticket.subject };
}

/** Write a chat reply. Mirrors `replyToConversation`'s exact prior DB-write body. */
export async function writeChatReply(args: {
  conversationId: string;
  body: string;
  /** The staff/admin user id the reply is attributed to (assignedToId). */
  staffId: string;
}): Promise<{ error?: string; ok?: boolean; conversationUserId?: string | null }> {
  const parsed = z
    .object({ id: z.string().min(1), body: z.string().trim().min(1).max(5000) })
    .safeParse({ id: args.conversationId, body: args.body });
  if (!parsed.success) return { error: "Message must be between 1 and 5000 characters." };

  const convo = await db.chatConversation.findUnique({ where: { id: parsed.data.id } });
  if (!convo) return { error: "Conversation not found." };

  await db.$transaction([
    db.chatMessage.create({
      data: { conversationId: parsed.data.id, sender: "agent", body: parsed.data.body },
    }),
    db.chatConversation.update({
      where: { id: parsed.data.id },
      data: {
        status: "OPEN",
        unreadForUser: true,
        unreadForAgent: false,
        assignedToId: args.staffId,
        lastMessageAt: new Date(),
      },
    }),
  ]);

  // If the visitor is a signed-in customer, drop them a notification.
  if (convo.userId) {
    await db.notification
      .create({
        data: {
          userId: convo.userId,
          title: "New reply in your live chat",
          href: "/dashboard",
        },
      })
      .catch(() => {});
  }

  return { ok: true, conversationUserId: convo.userId };
}
/**
 * Security core for support-ticket attachments.
 *
 * Mirrors lib/chat-attachment.ts's shape and guarantees (bytes validated by
 * *signature*, not the client-declared Content-Type; SVG never allowed) but
 * widens the allow-list beyond images: a ticket reply can also carry a PDF,
 * a plain-text/log file, or a ZIP — the file-upload button says "attach a
 * file", not "attach an image", so the validator has to mean that.
 *
 * Images are re-validated with lib/chat-attachment.ts's own sniffer rather
 * than a second copy of the magic-number table, so the two allow-lists can
 * never drift apart on what counts as a real PNG/JPEG/GIF/WEBP.
 */
import {
  ALLOWED_IMAGE_MIME,
  isAllowedImageMime,
  sniffImageMime,
  type AllowedImageMime,
} from "./chat-attachment";

/** Non-image document types a ticket attachment may declare. */
export const ALLOWED_DOC_MIME = [
  "application/pdf",
  "text/plain",
  "application/zip",
  "application/x-zip-compressed",
] as const;
export type AllowedDocMime = (typeof ALLOWED_DOC_MIME)[number];

/** `accept` attribute for the ticket file input: images + the document types above. */
export const TICKET_ACCEPT_ATTR = [
  ...ALLOWED_IMAGE_MIME,
  "application/pdf",
  ".pdf",
  "text/plain",
  ".txt",
  ".log",
  "application/zip",
  ".zip",
].join(",");

/**
 * Hard cap: 10 MB. A support attachment (log dump, screenshot, small PDF) runs
 * larger than a chat image; still well short of anything that would strain
 * storing bytes in Postgres. Enforced server-side regardless of any client check.
 */
export const MAX_TICKET_ATTACHMENT_BYTES = 10 * 1024 * 1024;

export type TicketAttachmentValidation =
  | { ok: true; mime: string; bytes: Buffer }
  | { ok: false; error: string };

function sniffPdf(buf: Buffer): boolean {
  // "%PDF"
  return buf.length >= 4 && buf[0] === 0x25 && buf[1] === 0x50 && buf[2] === 0x44 && buf[3] === 0x46;
}

function sniffZip(buf: Buffer): boolean {
  if (buf.length < 4) return false;
  // Local file header "PK\x03\x04", empty archive "PK\x05\x06", spanned "PK\x07\x08".
  if (buf[0] !== 0x50 || buf[1] !== 0x4b) return false;
  return (
    (buf[2] === 0x03 && buf[3] === 0x04) ||
    (buf[2] === 0x05 && buf[3] === 0x06) ||
    (buf[2] === 0x07 && buf[3] === 0x08)
  );
}

/**
 * Plain text/log has no magic number. Instead of trusting the extension alone,
 * reject anything that looks binary — a NUL byte, or a high proportion of
 * non-printable bytes, in the first 8 KB — the same heuristic tools like git
 * use to tell text from binary. This does not "validate" the content, it just
 * keeps an executable or image mislabeled as .txt from being accepted as one.
 */
function looksLikeText(buf: Buffer): boolean {
  const sample = buf.subarray(0, 8192);
  if (sample.length === 0) return true;
  let suspicious = 0;
  for (let i = 0; i < sample.length; i++) {
    const b = sample[i];
    if (b === 0) return false; // NUL byte: never text
    // Allow common whitespace control chars; count everything else below 0x20 as suspicious.
    if (b < 0x09 || (b > 0x0d && b < 0x20)) suspicious++;
  }
  return suspicious / sample.length < 0.05;
}

function extOf(filename: string | null | undefined): string {
  return (filename ?? "").toLowerCase().match(/\.[a-z0-9]{1,8}$/)?.[0] ?? "";
}

/**
 * Full server-side validation of a ticket attachment (image OR document).
 * Enforces, in order: non-empty, size ≤ cap, then dispatches to the right
 * signature check based on what the bytes actually look like — the declared
 * MIME/filename are only ever used to pick which check to try first, never
 * trusted on their own.
 */
export function validateTicketAttachmentBytes(
  bytes: Buffer | Uint8Array,
  declaredMime?: string | null,
  filename?: string | null
): TicketAttachmentValidation {
  const buf = Buffer.isBuffer(bytes) ? bytes : Buffer.from(bytes);

  if (buf.length === 0) return { ok: false, error: "Empty file." };
  if (buf.length > MAX_TICKET_ATTACHMENT_BYTES) {
    return { ok: false, error: "File is larger than 10 MB." };
  }

  const declared = (declaredMime ?? "").split(";")[0]?.trim().toLowerCase() || null;
  if (declared === "image/svg+xml") {
    return { ok: false, error: "SVG images are not allowed." };
  }

  // 1. Image — delegate to the shared image sniffer/allow-list.
  const sniffedImage = sniffImageMime(buf);
  if (sniffedImage) {
    if (declared && isAllowedImageMime(declared) && declared !== sniffedImage) {
      return { ok: false, error: "Image contents do not match its declared type." };
    }
    return { ok: true, mime: sniffedImage, bytes: buf };
  }
  if (declared && isAllowedImageMime(declared)) {
    // Claimed to be an allow-listed image but failed the byte signature check.
    return { ok: false, error: "File is not a supported image (PNG, JPEG, GIF, or WEBP)." };
  }

  // 2. PDF
  if (sniffPdf(buf)) return { ok: true, mime: "application/pdf", bytes: buf };
  if (declared === "application/pdf") {
    return { ok: false, error: "File is not a valid PDF." };
  }

  // 3. ZIP
  if (sniffZip(buf)) return { ok: true, mime: "application/zip", bytes: buf };
  if (declared === "application/zip" || declared === "application/x-zip-compressed") {
    return { ok: false, error: "File is not a valid ZIP archive." };
  }

  // 4. Plain text / log — no magic number, so lean on extension + a binary-content check.
  const ext = extOf(filename);
  const looksLikeTextFile = declared === "text/plain" || ext === ".txt" || ext === ".log";
  if (looksLikeTextFile) {
    if (!looksLikeText(buf)) {
      return { ok: false, error: "File does not look like a plain-text/log file." };
    }
    return { ok: true, mime: "text/plain", bytes: buf };
  }

  return {
    ok: false,
    error: "Unsupported file type. Allowed: images, PDF, TXT, LOG, or ZIP.",
  };
}

export function isImageMime(mime: string): mime is AllowedImageMime {
  return isAllowedImageMime(mime);
}
import "server-only";
import { db } from "./db";
import { sendMail, emails } from "./mailer";

/**
 * Customer-facing "ticket reply" email send governance — coalescing +
 * circuit breaker.
 *
 * WHY THIS EXISTS (2026-08-31 incident). Two customers each received a burst
 * of 12-20 separate "New reply" emails inside a few hours. Root-caused
 * against EmailLog + TicketMessage: every single one was a genuinely
 * distinct, staff-authored reply (unique body, unique timestamp, no
 * retry-loop, no duplicate rows — image attachments behaved no differently
 * than any other reply, ruling out the suspected upload-callback theory).
 * This was a human support agent working a fast-moving live conversation,
 * not a bug that resent the same message — but Gmail's per-recipient abuse
 * heuristic (421-4.7.28 "unusual rate of unsolicited mail") doesn't care that
 * the content differed, only that mail.nxeon.cloud hit one mailbox that many
 * times that fast, and it started throttling that recipient — a real
 * deliverability risk to every OTHER transactional email (password resets,
 * receipts) this domain sends. There was no dedup/rate limit anywhere in
 * this path, so nothing stopped a legitimately chatty conversation — or any
 * FUTURE bug shaped like this one — from tripping it again.
 *
 * TWO SEPARATE SAFEGUARDS, BOTH IN THIS FILE:
 *
 * 1. COALESCE WINDOW (`TICKET_REPLY_COALESCE_MS`) — staff replies to the same
 *    ticket that land within this window of an already-sent email do not
 *    each get their own email. `maybeSendTicketReplyEmail` (called inline,
 *    right after a staff TicketMessage is written) sends immediately when
 *    the ticket has been quiet — the common case, zero added latency. When
 *    it's NOT quiet (we're inside another send's window), it does nothing
 *    and leaves the burst for `worker/ticket-reply-digest.ts`'s periodic
 *    sweep to flush as ONE email once the burst goes quiet — bounded delay,
 *    nothing silently dropped. Real support replies are normally minutes to
 *    hours apart, so this never delays a normal conversation; it only
 *    collapses genuine rapid-fire bursts (human or bug).
 *
 * 2. DAILY CAP (`TICKET_REPLY_DAILY_CAP`) — a hard circuit breaker,
 *    independent of the coalescing above. If a single customer would cross
 *    this many ticket_reply emails in a rolling 24h window, further sends
 *    stop automatically and staff get an admin Notification instead of the
 *    customer getting another email — a backstop against ANY future bug
 *    shaped like this one, not just today's specific cause. Deliberately NOT
 *    a flat "once per day" limit — a real multi-touch ticket (status update,
 *    then "fixed" a few hours later) must not get throttled into a bad
 *    support experience; the cap only bites at genuinely abnormal volume.
 *
 * Neither safeguard touches the TicketMessage write, the in-app bell
 * notification, or the Discord mirror — those still fire on every reply.
 * Only the outbound customer email is governed here.
 */

/** Staff replies to the same ticket inside this window of an already-sent
 *  email collapse into a single follow-up email instead of one each. */
export const TICKET_REPLY_COALESCE_MS = 2 * 60_000;

/** Circuit breaker: max ticket_reply emails one customer may receive in a
 *  rolling 24h window before further ones are suppressed and flagged. */
export const TICKET_REPLY_DAILY_CAP = 5;

const DAILY_WINDOW_MS = 24 * 3600_000;

/** The subject tag `emails.ticketReply` stamps on every send — used to scope
 *  EmailLog lookups to THIS ticket without a schema change. */
export function ticketReplyEmailTag(ticketId: string): string {
  return `[#${ticketId}]`;
}

/** How many ticket_reply emails has this customer been sent in the last 24h? */
export async function ticketReplyDailyCount(customerUserId: string, now: Date = new Date()): Promise<number> {
  return db.emailLog.count({
    where: {
      userId: customerUserId,
      template: "ticket_reply",
      status: "SENT",
      createdAt: { gte: new Date(now.getTime() - DAILY_WINDOW_MS) },
    },
  });
}

/** Most recent SENT ticket_reply email for this exact ticket, if any. */
async function lastSentTicketReplyEmail(ticketId: string, customerUserId: string): Promise<{ createdAt: Date } | null> {
  return db.emailLog.findFirst({
    where: {
      userId: customerUserId,
      template: "ticket_reply",
      status: "SENT",
      subject: { startsWith: ticketReplyEmailTag(ticketId) },
    },
    orderBy: { createdAt: "desc" },
    select: { createdAt: true },
  });
}

/**
 * Flag the daily cap having been reached for staff attention. Deduped to at
 * most one admin Notification per ticket per hour so a still-active
 * conversation past the cap doesn't spam the admin bell on every further
 * reply attempt.
 */
export async function flagTicketReplyDailyCapReached(ticketId: string, ticketSubject: string): Promise<void> {
  const dedupeSince = new Date(Date.now() - 60 * 60_000);
  const href = `/admin/support/${ticketId}`;
  const already = await db.notification.findFirst({
    where: { href, title: { startsWith: "⚠️ Ticket reply emails paused" }, createdAt: { gte: dedupeSince } },
  });
  if (already) return;
  console.warn(
    `[support] ticket-reply daily email cap (${TICKET_REPLY_DAILY_CAP}/24h) reached for ticket ${ticketId} — further customer emails suppressed until it rolls off`,
  );
  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
  if (admins.length === 0) return;
  await db.notification.createMany({
    data: admins.map((a) => ({
      userId: a.id,
      title: `⚠️ Ticket reply emails paused (daily cap reached): ${ticketSubject}`,
      href,
    })),
  });
}

/** Actually render + send the customer-facing "ticket reply" email. No
 *  governance here — callers (the fast path below, and the digest sweep)
 *  are responsible for deciding it's OK to send. */
export async function sendTicketReplyEmailNow(
  ticketId: string,
  customerUserId: string,
  customerEmail: string,
  ticketSubject: string,
  replyPreview: string,
): Promise<void> {
  const tpl = emails.ticketReply({ ticketId, subject: ticketSubject, replyPreview });
  await sendMail({
    to: customerEmail,
    subject: tpl.subject,
    html: tpl.html,
    template: tpl.template,
    userId: customerUserId,
    kind: "support_reply",
  });
}

/**
 * Called synchronously right after a staff TicketMessage is written
 * (`lib/reply-core.ts`'s `writeTicketReply`). Fast path for the normal case;
 * defers to `worker/ticket-reply-digest.ts`'s sweep when we're mid-burst.
 * Never throws — a mail failure or governance skip must never fail the reply
 * itself; callers still wrap this in their own try/catch as defense in depth.
 */
export async function maybeSendTicketReplyEmail(args: {
  ticketId: string;
  ticketUserId: string;
  ticketSubject: string;
  replyBody: string;
}): Promise<void> {
  const sentToday = await ticketReplyDailyCount(args.ticketUserId);
  if (sentToday >= TICKET_REPLY_DAILY_CAP) {
    await flagTicketReplyDailyCapReached(args.ticketId, args.ticketSubject);
    return;
  }

  const lastSent = await lastSentTicketReplyEmail(args.ticketId, args.ticketUserId);
  if (lastSent && Date.now() - lastSent.createdAt.getTime() < TICKET_REPLY_COALESCE_MS) {
    // Inside another send's coalesce window — leave this burst for the
    // digest sweep to flush as one email once it goes quiet.
    console.info("[support] staff-reply email deferred to digest sweep (coalesce window)", args.ticketId);
    return;
  }

  const customer = await db.user.findUnique({ where: { id: args.ticketUserId }, select: { email: true } });
  if (!customer?.email) return;
  await sendTicketReplyEmailNow(args.ticketId, args.ticketUserId, customer.email, args.ticketSubject, args.replyBody);
}
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { isStaff } from "@/lib/rbac";
import { isImageMime } from "@/lib/ticket-attachment";

export const runtime = "nodejs";

/**
 * GET /api/tickets/attachment/[id] — stream a ticket-message attachment ONLY
 * to an authorized viewer: any staff member (SUPPORT/ADMIN), or the customer
 * who owns the ticket the message belongs to. Mirrors the authorization model
 * and response hardening of app/api/chat/attachment/[id]/route.ts.
 *
 * `id` is the TicketMessage id (a database id, never a filename — no path
 * traversal). Images are served inline for preview; every other allowed type
 * (PDF/TXT/ZIP) is served as a download so nothing can render as a document in
 * the browsing context regardless of what a mislabeled file claims to be.
 */
export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  if (typeof id !== "string" || !id) return new Response("Not found", { status: 404 });

  const message = await db.ticketMessage.findUnique({
    where: { id },
    select: {
      attachmentData: true,
      attachmentMime: true,
      attachmentName: true,
      ticket: { select: { userId: true } },
    },
  });
  if (!message || !message.attachmentData || !message.attachmentMime) {
    return new Response("Not found", { status: 404 });
  }

  const user = await currentUser();
  const authorized = !!user && (isStaff(user.role) || user.id === message.ticket.userId);
  if (!authorized) return new Response("Forbidden", { status: 403 });

  const mime = message.attachmentMime;
  const isImage = isImageMime(mime);
  const data: Buffer = Buffer.isBuffer(message.attachmentData)
    ? message.attachmentData
    : Buffer.from(message.attachmentData as Uint8Array);

  const safeName = (message.attachmentName ?? "attachment").replace(/["\r\n]/g, "");
  const disposition = isImage ? `inline; filename="${safeName}"` : `attachment; filename="${safeName}"`;

  return new Response(new Uint8Array(data), {
    status: 200,
    headers: {
      "Content-Type": mime,
      "Content-Length": String(data.length),
      "Content-Disposition": disposition,
      "X-Content-Type-Options": "nosniff",
      "Content-Security-Policy": "default-src 'none'; sandbox",
      "Cache-Control": "private, max-age=86400, no-transform",
    },
  });
}
// Ticket-reply email digest sweep (worker task).
//
// Registered on the worker loop (worker/index.ts). Flushes the "one email per
// burst" side of `lib/ticket-reply-email.ts`'s coalescing safeguard — see that
// file's top-of-file comment for the full incident writeup and design.
//
// `maybeSendTicketReplyEmail` (called inline from `lib/reply-core.ts` right
// after a staff reply is written) sends immediately when a ticket has been
// quiet for a while (the common case). When a new staff reply lands inside
// another send's `TICKET_REPLY_COALESCE_MS` window, it deliberately does
// NOTHING — no email goes out for that reply. This sweep is what guarantees
// that burst still gets exactly ONE follow-up email once it goes quiet,
// instead of the customer's latest update just silently never being mailed.
//
// FINDING CANDIDATES WITHOUT A SCHEMA CHANGE: there is no "pending digest"
// column anywhere. Instead this derives pending state from data that already
// exists — any ticket with a staff-authored TicketMessage newer than that
// ticket's most recent SENT `ticket_reply` EmailLog row is "behind" and needs
// a catch-up email once the newest such message has been quiet long enough.
// Scoped to staff messages from the last 30 minutes: `TICKET_REPLY_COALESCE_MS`
// is only 2 minutes, so anything that could still be "pending and not yet
// quiet long enough" is always well inside that lookback; this just bounds
// the scan to recent activity instead of walking every ticket that ever
// existed. (If ticket volume grows enough for this per-tick scan to matter,
// the natural next step is a real `pendingReplyEmailSince` column — not done
// here since the current volume makes it unnecessary and this ships faster
// without a migration during an active incident.)
//
// Polled every ~20s (see worker/index.ts) — short enough that the 2-minute
// coalesce window doesn't turn into a much longer real-world delay.

import { db } from "../lib/db";
import {
  TICKET_REPLY_COALESCE_MS,
  TICKET_REPLY_DAILY_CAP,
  ticketReplyEmailTag,
  ticketReplyDailyCount,
  flagTicketReplyDailyCapReached,
  sendTicketReplyEmailNow,
} from "../lib/ticket-reply-email";

/** How far back to look for candidate tickets. Generous relative to the
 *  2-minute coalesce window so a sweep hiccup can't miss a pending burst. */
const CANDIDATE_LOOKBACK_MS = 30 * 60_000;

/** Bounded per-sweep-tick send budget — mirrors the pattern in
 *  lib/critical-email-retry.ts: a backlog can't hammer the mail relay. */
const MAX_SENDS_PER_SWEEP = 20;

/** Gentle pacing between sends within one sweep tick. */
const SEND_GAP_MS = 500;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export async function ticketReplyDigestSweep(): Promise<void> {
  const since = new Date(Date.now() - CANDIDATE_LOOKBACK_MS);

  // Distinct tickets that had a staff reply recently — candidates for "is
  // this ticket behind on its customer-facing email?".
  const recentStaffMessages = await db.ticketMessage.findMany({
    where: { isStaff: true, createdAt: { gte: since } },
    distinct: ["ticketId"],
    select: { ticketId: true },
  });
  if (recentStaffMessages.length === 0) return;

  let sent = 0;
  for (const { ticketId } of recentStaffMessages) {
    if (sent >= MAX_SENDS_PER_SWEEP) break;

    const latestStaffMessage = await db.ticketMessage.findFirst({
      where: { ticketId, isStaff: true },
      orderBy: { createdAt: "desc" },
      select: { createdAt: true, body: true },
    });
    if (!latestStaffMessage) continue;

    // Still inside the coalesce window since this ticket's newest staff
    // reply — not quiet yet, leave it for a later tick (or the inline fast
    // path may still catch it if this is actually the very first reply).
    if (Date.now() - latestStaffMessage.createdAt.getTime() < TICKET_REPLY_COALESCE_MS) continue;

    const ticket = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true, subject: true } });
    if (!ticket) continue;

    const lastSentEmail = await db.emailLog.findFirst({
      where: {
        userId: ticket.userId,
        template: "ticket_reply",
        status: "SENT",
        subject: { startsWith: ticketReplyEmailTag(ticketId) },
      },
      orderBy: { createdAt: "desc" },
      select: { createdAt: true },
    });
    // Already caught up — the fast path already mailed this exact reply (or a
    // later one hasn't landed yet). Nothing to flush.
    if (lastSentEmail && lastSentEmail.createdAt >= latestStaffMessage.createdAt) continue;

    if ((await ticketReplyDailyCount(ticket.userId)) >= TICKET_REPLY_DAILY_CAP) {
      await flagTicketReplyDailyCapReached(ticketId, ticket.subject);
      continue;
    }

    const customer = await db.user.findUnique({ where: { id: ticket.userId }, select: { email: true } });
    if (!customer?.email) continue;

    try {
      await sendTicketReplyEmailNow(ticketId, ticket.userId, customer.email, ticket.subject, latestStaffMessage.body);
      sent++;
      await sleep(SEND_GAP_MS);
    } catch (e) {
      console.error("[ticket-reply-digest] send failed (non-fatal)", ticketId, e);
    }
  }
}

"use client";

import { forwardRef, useImperativeHandle, useRef, useState, type ClipboardEvent } from "react";
import { VoiceMicButton } from "./VoiceMicButton";

/**
 * Client-side `accept` string only — deliberately NOT imported from
 * lib/ticket-attachment.ts. That module (and lib/chat-attachment.ts beneath
 * it) uses `Buffer`, which has no business in a client bundle; the real
 * validation always happens server-side in `replyTicket`/`writeTicketReply`
 * regardless of what this attribute lets the picker show. Mirrors
 * components/ChatWidget.tsx's own local `ACCEPT_IMAGES` constant for the
 * same reason.
 */
const ACCEPT_ATTR =
  "image/png,image/jpeg,image/gif,image/webp,application/pdf,.pdf,text/plain,.txt,.log,application/zip,.zip";

export type ReplyComposerHandle = { resetAttachment: () => void };

/**
 * Shared reply-box chrome for both the admin (`TicketControls.tsx`) and
 * customer (`TicketForms.tsx`) reply forms: the textarea itself, a paperclip
 * file picker, paste-an-image-from-clipboard support, and the voice-dictation
 * mic button. Renders a hidden `<input type="file" name="file">` INSIDE the
 * enclosing `<form>` so a pasted image (attached via the DataTransfer trick
 * below) rides along with a normal form-action submit — no extra JS wiring
 * needed at the call site beyond mounting this component inside the form.
 */
export const ReplyComposer = forwardRef<
  ReplyComposerHandle,
  {
    value: string;
    onChange: (value: string) => void;
    placeholder?: string;
    disabled?: boolean;
    className?: string;
  }
>(function ReplyComposer({ value, onChange, placeholder, disabled, className }, ref) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [attachedName, setAttachedName] = useState<string | null>(null);

  useImperativeHandle(ref, () => ({
    resetAttachment: clearAttachment,
  }));

  function clearAttachment() {
    if (fileInputRef.current) fileInputRef.current.value = "";
    setAttachedName(null);
  }

  function handlePaste(e: ClipboardEvent<HTMLTextAreaElement>) {
    const item = Array.from(e.clipboardData?.items ?? []).find((i) => i.type.startsWith("image/"));
    if (!item) return;
    const file = item.getAsFile();
    if (!file) return;
    e.preventDefault();
    const dt = new DataTransfer();
    dt.items.add(new File([file], file.name || "pasted-image.png", { type: file.type || "image/png" }));
    if (fileInputRef.current) fileInputRef.current.files = dt.files;
    setAttachedName(file.name || "pasted-image.png");
  }

  return (
    <div className={className}>
      <textarea
        className="input min-h-28 resize-y"
        name="body"
        placeholder={placeholder}
        disabled={disabled}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onPaste={handlePaste}
      />
      <input
        ref={fileInputRef}
        type="file"
        name="file"
        accept={ACCEPT_ATTR}
        className="hidden"
        disabled={disabled}
        onChange={(e) => setAttachedName(e.target.files?.[0]?.name ?? null)}
      />
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <button
          type="button"
          disabled={disabled}
          onClick={() => fileInputRef.current?.click()}
          title="Attach a file"
          className="inline-flex items-center gap-1.5 rounded-full border border-white/10 bg-white/5 px-2.5 py-1 text-xs text-slate-300 transition hover:bg-white/10"
        >
          <span aria-hidden>📎</span> Attach
        </button>
        <VoiceMicButton disabled={disabled} onTranscript={(t) => onChange(value ? `${value} ${t}` : t)} />
        {attachedName && (
          <span className="inline-flex items-center gap-1.5 rounded-full border border-brand-500/30 bg-brand-500/10 px-2.5 py-1 text-xs text-brand-200">
            {attachedName}
            <button
              type="button"
              onClick={clearAttachment}
              aria-label="Remove attachment"
              className="text-brand-300/70 hover:text-red-400"
            >
              ×
            </button>
          </span>
        )}
      </div>
    </div>
  );
});
import { fmtBytes } from "@/components/ui/primitives";

/**
 * Renders a ticket message's single attachment (see prisma/schema.prisma's
 * `TicketMessage.attachment*` columns): an inline preview for images, or a
 * filename + size download chip for everything else. Bytes are streamed from
 * `/api/tickets/attachment/[messageId]`, which re-checks authorization on
 * every request rather than trusting that the page that rendered this link
 * was itself authorized. Server-renderable — no interactivity needed here.
 */
export function MessageAttachment({
  messageId,
  mime,
  name,
  size,
}: {
  messageId: string;
  mime: string;
  name: string;
  size: number;
}) {
  const url = `/api/tickets/attachment/${messageId}`;
  const isImage = mime.startsWith("image/");

  if (isImage) {
    return (
      // eslint-disable-next-line @next/next/no-img-element -- served from our own
      // authorization-checked route, not a static/optimizable asset path.
      <a href={url} target="_blank" rel="noopener noreferrer" className="mt-2 block">
        <img
          src={url}
          alt={name}
          className="max-h-64 rounded-lg border border-white/10 object-contain"
        />
      </a>
    );
  }

  return (
    <a
      href={url}
      download={name}
      className="mt-2 flex items-center gap-2 rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-xs text-slate-300 transition hover:bg-white/10"
    >
      <span aria-hidden>📄</span>
      <span className="truncate">{name}</span>
      <span className="ml-auto shrink-0 text-slate-500">{fmtBytes(size)}</span>
    </a>
  );
}
"use client";

import { useEffect, useState, useTransition } from "react";
import { editTicketMessage } from "@/lib/actions-support";
import { TicketBody } from "./TicketBody";

const EDIT_WINDOW_MS = 5 * 60_000;

/**
 * Renders a single message's body, with an "Edit" affordance that appears
 * only for the message's own author and only within 5 minutes of sending —
 * matched to the server-side window `editTicketMessage` (lib/actions-support.ts)
 * actually enforces. This client-side countdown is a UX nicety ONLY: hiding
 * the button here is not what stops a late edit, the server re-checks
 * `createdAt` itself and rejects regardless of what this component shows.
 *
 * The "(edited)" label is shown to BOTH admin and customer views (pass this
 * component to either) — unlike read receipts, an edit marker is a
 * transparency signal both parties see.
 */
export function EditableMessageBody({
  messageId,
  initialBody,
  createdAtIso,
  editedAtIso,
  canEditPermission,
  bodyClassName,
}: {
  messageId: string;
  initialBody: string;
  createdAtIso: string;
  editedAtIso: string | null;
  /** Author-matches-viewer AND ticket-not-closed — everything except the time window. */
  canEditPermission: boolean;
  bodyClassName: string;
}) {
  const [body, setBody] = useState(initialBody);
  const [editedAt, setEditedAt] = useState(editedAtIso);
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(initialBody);
  const [error, setError] = useState<string | null>(null);
  const [withinWindow, setWithinWindow] = useState(
    () => Date.now() - new Date(createdAtIso).getTime() < EDIT_WINDOW_MS
  );
  const [pending, start] = useTransition();

  useEffect(() => {
    if (!canEditPermission || !withinWindow) return;
    const id = window.setInterval(() => {
      const stillWithin = Date.now() - new Date(createdAtIso).getTime() < EDIT_WINDOW_MS;
      setWithinWindow(stillWithin);
      if (!stillWithin) window.clearInterval(id);
    }, 5_000);
    return () => window.clearInterval(id);
  }, [canEditPermission, withinWindow, createdAtIso]);

  function save() {
    setError(null);
    start(async () => {
      const res = await editTicketMessage(messageId, draft);
      if (res?.error) {
        setError(res.error);
        return;
      }
      setBody(draft.trim());
      setEditedAt(new Date().toISOString());
      setEditing(false);
    });
  }

  if (editing) {
    return (
      <div className="space-y-2">
        <textarea
          className="input min-h-20 w-full resize-y text-sm"
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          disabled={pending}
          autoFocus
        />
        {error && <p className="text-xs text-red-400">{error}</p>}
        <div className="flex items-center gap-2">
          <button
            type="button"
            className="btn-primary px-3 py-1 text-xs"
            disabled={pending || draft.trim().length < 2}
            onClick={save}
          >
            {pending ? "Saving…" : "Save"}
          </button>
          <button
            type="button"
            className="btn-ghost px-3 py-1 text-xs"
            disabled={pending}
            onClick={() => {
              setDraft(body);
              setError(null);
              setEditing(false);
            }}
          >
            Cancel
          </button>
        </div>
      </div>
    );
  }

  return (
    <div>
      <TicketBody text={body} className={bodyClassName} />
      <div className="mt-1 flex items-center gap-2">
        {editedAt && <span className="text-[10px] text-slate-500">(edited)</span>}
        {canEditPermission && withinWindow && (
          <button
            type="button"
            className="text-[10px] text-slate-500 underline decoration-dotted hover:text-brand-300"
            onClick={() => {
              setDraft(body);
              setEditing(true);
            }}
          >
            Edit
          </button>
        )}
      </div>
    </div>
  );
}
"use client";

import { useEffect, useRef, useState } from "react";

/**
 * Voice-to-text mic button for a reply textarea, built on the browser's native
 * Web Speech API (`SpeechRecognition` / the WebKit-prefixed variant) — no
 * server round trip, no third-party service, nothing to configure.
 *
 * Firefox (and any other browser without the API) simply never renders this
 * button — feature-detected once on mount, not caught-and-hidden after a
 * broken click. Click once to start listening (the button shows a pulsing
 * "Listening…" state), click again — or let it finish on silence — to stop;
 * each final transcript chunk is appended to the caller's current text via
 * `onTranscript`.
 */

// Minimal shape of the API this component actually uses — `lib.dom.d.ts` does
// not (yet) ship types for SpeechRecognition, so this is deliberately narrow
// rather than reaching for `any` everywhere below.
interface MinimalSpeechRecognition extends EventTarget {
  continuous: boolean;
  interimResults: boolean;
  lang: string;
  start(): void;
  stop(): void;
  onresult: ((event: any) => void) | null;
  onend: (() => void) | null;
  onerror: ((event: any) => void) | null;
}

type SpeechRecognitionCtor = new () => MinimalSpeechRecognition;

function getSpeechRecognitionCtor(): SpeechRecognitionCtor | null {
  if (typeof window === "undefined") return null;
  const w = window as unknown as {
    SpeechRecognition?: SpeechRecognitionCtor;
    webkitSpeechRecognition?: SpeechRecognitionCtor;
  };
  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
}

export function VoiceMicButton({
  onTranscript,
  disabled,
}: {
  onTranscript: (text: string) => void;
  disabled?: boolean;
}) {
  const [supported, setSupported] = useState(false);
  const [listening, setListening] = useState(false);
  const recognitionRef = useRef<MinimalSpeechRecognition | null>(null);

  useEffect(() => {
    setSupported(getSpeechRecognitionCtor() !== null);
    return () => {
      recognitionRef.current?.stop();
    };
  }, []);

  if (!supported) return null;

  function start() {
    const Ctor = getSpeechRecognitionCtor();
    if (!Ctor) return;
    const recognition = new Ctor();
    recognition.continuous = true;
    recognition.interimResults = false;
    recognition.lang = typeof navigator !== "undefined" ? navigator.language : "en-US";

    recognition.onresult = (event: any) => {
      let finalText = "";
      for (let i = event.resultIndex; i < event.results.length; i++) {
        const result = event.results[i];
        if (result.isFinal) finalText += result[0].transcript;
      }
      if (finalText.trim()) onTranscript(finalText.trim());
    };
    recognition.onerror = () => {
      setListening(false);
    };
    recognition.onend = () => {
      setListening(false);
    };

    recognitionRef.current = recognition;
    recognition.start();
    setListening(true);
  }

  function stop() {
    recognitionRef.current?.stop();
    setListening(false);
  }

  return (
    <button
      type="button"
      disabled={disabled}
      onClick={() => (listening ? stop() : start())}
      title={listening ? "Stop dictation" : "Dictate with your microphone"}
      aria-pressed={listening}
      className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-xs transition ${
        listening
          ? "animate-pulse border-red-500/40 bg-red-500/10 text-red-300"
          : "border-white/10 bg-white/5 text-slate-300 hover:bg-white/10"
      }`}
    >
      <span aria-hidden>🎤</span>
      {listening ? "Listening…" : "Dictate"}
    </button>
  );
}
/**
 * Read/delivered indicator for a STAFF message, rendered on the ADMIN side
 * only (see app/admin/support/[id]/page.tsx). iMessage/WhatsApp-style: a
 * single check for "sent, not yet read by the customer", a double check in
 * brand color once `readAt` is set. The timestamp shows on hover via the
 * native `title` attribute — no client JS needed for this alone.
 *
 * Deliberately has no customer-facing counterpart. Per the explicit design
 * ("read receipts from customers, but they dont get them from us"), the
 * customer thread (app/dashboard/support/[id]/page.tsx) never renders this
 * component at all — for staff messages OR for the customer's own.
 */
export function ReadReceipt({ readAt }: { readAt: Date | null }) {
  if (readAt) {
    return (
      <span
        className="inline-flex items-center gap-1 text-[11px] text-brand-300"
        title={`Read ${readAt.toLocaleString()}`}
      >
        <span aria-hidden>✓✓</span> Read
      </span>
    );
  }
  return (
    <span className="inline-flex items-center gap-1 text-[11px] text-slate-500" title="Sent — not yet read">
      <span aria-hidden>✓</span> Delivered
    </span>
  );
}
"use client";

import { useEffect, useState } from "react";
import { listCannedReplies, type CannedReplyItem } from "@/lib/actions-canned-replies";

/**
 * Quick-replies snippet picker, shared between the ticket reply form
 * (components/admin/TicketControls.tsx) and the live-chat reply box
 * (components/admin/ChatInbox.tsx). v1 on purpose: a plain `<select>` that
 * appends the chosen snippet's body onto whatever the agent has already
 * typed — no rich-text merge, no keyboard-shortcut trigger. The list loads
 * client-side via `listCannedReplies` (already gated
 * requireAnyGrant(["supportTickets","liveChat"]) in
 * lib/actions-canned-replies.ts), so this renders nothing extra for a caller
 * who somehow reaches it without either grant — the action call simply
 * throws and the catch below leaves the picker empty rather than crashing
 * the reply box around it.
 */
export function CannedReplyPicker({
  onInsert,
  disabled,
}: {
  onInsert: (body: string) => void;
  disabled?: boolean;
}) {
  const [replies, setReplies] = useState<CannedReplyItem[]>([]);

  useEffect(() => {
    let alive = true;
    listCannedReplies()
      .then((rows) => alive && setReplies(rows))
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, []);

  if (replies.length === 0) return null;

  return (
    <select
      aria-label="Insert a canned reply"
      className="input w-auto py-1.5 text-xs"
      value=""
      disabled={disabled}
      onChange={(e) => {
        const reply = replies.find((r) => r.id === e.target.value);
        if (reply) onInsert(reply.body);
        e.target.value = "";
      }}
    >
      <option value="" disabled>
        Insert canned reply…
      </option>
      {replies.map((r) => (
        <option key={r.id} value={r.id}>
          {r.title}
        </option>
      ))}
    </select>
  );
}
import { Fragment, type ReactNode } from "react";

/**
 * Renders a ticket message body with light formatting — fenced code blocks,
 * inline code, and auto-highlighted IP addresses and domains — for both the
 * customer and admin ticket views (via EditableMessageBody).
 *
 * ─── WHY THIS IS BUILT FROM REACT ELEMENTS, NEVER innerHTML ──────────────────
 * A ticket body is UNTRUSTED input: customers type it. Rendering it through
 * `dangerouslySetInnerHTML` — even after a markdown pass — is a stored-XSS
 * vector (one crafted message runs script in a staff member's admin session).
 * So this tokenizes the raw string and emits ONLY text nodes and styled spans;
 * every character the user typed lands as text content, never as markup. The
 * "formatting" is pattern recognition over plain text, not HTML the user
 * supplied.
 *
 * Recognised, in order:
 *   1. ``` fenced code blocks ```  → a monospace <pre> block (verbatim).
 *   2. `inline code`               → a monospace chip (verbatim).
 *   3. http(s) URLs + bare domains → clickable links (new tab, noopener), in
 *      prose only. The href is ALWAYS one we built — the matched http(s) URL, or
 *      a bare domain we prefix with https:// — and is scheme-checked, so a
 *      `javascript:`/`data:` payload in a customer message can never become a
 *      link target.
 *   4. IPv4 (opt :port)            → a colored monospace chip (not clickable).
 * Code spans are left verbatim on purpose — a URL or IP inside a command should
 * read as part of the command, not get linkified/re-chipped.
 */

// IPv4 with an optional :port. Octet-accurate so "8.3" or a version string can't
// masquerade as an address. Bounded by \b so it doesn't grab a trailing digit run.
const IP_SOURCE =
  "\\b(?:(?:25[0-5]|2[0-4]\\d|1?\\d?\\d)\\.){3}(?:25[0-5]|2[0-4]\\d|1?\\d?\\d)(?::\\d{1,5})?\\b";
// A domain: one or more labels then an ALPHA TLD (2–24). The alpha-TLD rule is
// what stops "php8.3", "0.0.0.0", or "e.g" from matching — a numeric last label
// is never a domain here.
const DOMAIN_SOURCE =
  "\\b(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\\.)+[a-zA-Z]{2,24}\\b";
// A full http(s) URL. Kept greedy to the first whitespace/quote/angle, then the
// trailing sentence punctuation is trimmed after the match (see trimUrlTail) so
// "see https://x.com/y." doesn't swallow the period into the link.
const URL_SOURCE = "https?://[^\\s<>\"'`]+";
// URL alternative FIRST (a URL contains a domain and could contain a dotted host),
// then IP so a dotted-quad is an IP not a failed domain, then bare domain.
const ENTITY_RE = new RegExp(`(${URL_SOURCE})|(${IP_SOURCE})|(${DOMAIN_SOURCE})`, "g");

/** Trailing chars that are almost always sentence punctuation, not part of a URL. */
function trimUrlTail(url: string): { url: string; tail: string } {
  const m = /[.,;:!?)\]}'"]+$/.exec(url);
  // Keep a closing paren only if the URL also contains an opening one (wiki-style).
  if (!m) return { url, tail: "" };
  let cut = m[0];
  if (cut.includes(")") && (url.match(/\(/g)?.length ?? 0) >= (url.match(/\)/g)?.length ?? 0)) {
    cut = cut.replace(/\)+$/, "");
  }
  return cut ? { url: url.slice(0, url.length - cut.length), tail: cut } : { url, tail: "" };
}

/**
 * Only ever produce an href we built ourselves from a matched http(s) URL or a
 * bare domain we prefix with https://. A user's text can never inject a
 * `javascript:`/`data:` scheme this way — the scheme is always http/https by
 * construction — but assert it anyway as defense in depth.
 */
function safeHref(href: string): string | null {
  return /^https?:\/\//i.test(href) ? href : null;
}

const LINK_CLASS =
  "font-mono text-[0.95em] text-accent-blue underline decoration-dotted underline-offset-2 hover:text-brand-300 break-all";

/** Highlight URLs (clickable), bare domains (clickable), and IPs (chip) in prose. */
function highlightEntities(text: string, keyBase: string): ReactNode[] {
  const out: ReactNode[] = [];
  let last = 0;
  let m: RegExpExecArray | null;
  ENTITY_RE.lastIndex = 0;
  let i = 0;
  while ((m = ENTITY_RE.exec(text)) !== null) {
    const isUrl = m[1] !== undefined;
    const isIp = m[2] !== undefined;
    let matchText = m[0];
    let tail = "";
    if (isUrl) {
      const trimmed = trimUrlTail(matchText);
      matchText = trimmed.url;
      tail = trimmed.tail;
    }
    if (m.index > last) out.push(text.slice(last, m.index));

    if (isUrl || (!isIp && safeHref(`https://${matchText}`))) {
      // URL as-is; bare domain gets an https:// scheme for the href but shows raw.
      const href = safeHref(isUrl ? matchText : `https://${matchText}`);
      if (href) {
        out.push(
          <a key={`${keyBase}-e${i++}`} href={href} target="_blank" rel="noopener noreferrer nofollow" className={LINK_CLASS}>
            {matchText}
          </a>
        );
      } else {
        out.push(matchText);
      }
    } else {
      // IP address: informational chip, not a link.
      out.push(
        <span key={`${keyBase}-e${i++}`} className="rounded bg-accent-cyan/10 px-1 font-mono text-[0.9em] text-accent-cyan">
          {matchText}
        </span>
      );
    }
    if (tail) out.push(tail);
    last = m.index + m[0].length;
  }
  if (last < text.length) out.push(text.slice(last));
  return out;
}

/** Split a prose run on `inline code`, highlighting entities in the gaps. */
function renderProse(text: string, keyBase: string): ReactNode[] {
  const parts = text.split(/(`[^`\n]+`)/g);
  return parts.map((part, idx) => {
    if (part.length >= 2 && part.startsWith("`") && part.endsWith("`")) {
      return (
        <code
          key={`${keyBase}-c${idx}`}
          className="rounded border border-white/10 bg-white/[0.06] px-1.5 py-0.5 font-mono text-[0.85em] text-slate-300"
        >
          {part.slice(1, -1)}
        </code>
      );
    }
    return <Fragment key={`${keyBase}-t${idx}`}>{highlightEntities(part, `${keyBase}-t${idx}`)}</Fragment>;
  });
}

export function TicketBody({ text, className }: { text: string; className?: string }) {
  // Split on fenced code blocks. The capturing group keeps the fences' contents;
  // even indices are prose, odd indices are code-block bodies.
  const segments = text.split(/```([\s\S]*?)```/g);

  return (
    <div className={className}>
      {segments.map((seg, idx) => {
        if (idx % 2 === 1) {
          // Fenced code block. Drop an optional leading language hint (```bash).
          const body = seg.replace(/^[ \t]*[a-zA-Z0-9_+-]*[ \t]*\n/, "").replace(/\n$/, "");
          return (
            <pre
              key={`b${idx}`}
              className="my-2 overflow-x-auto rounded-lg border border-white/10 bg-navy-950/80 p-3 font-mono text-xs leading-relaxed text-slate-200"
            >
              {body}
            </pre>
          );
        }
        if (seg === "") return null;
        return <Fragment key={`p${idx}`}>{renderProse(seg, `p${idx}`)}</Fragment>;
      })}
    </div>
  );
}

import "server-only";
import type { Role } from "@prisma/client";
import { db } from "./db";
import { canAccess } from "./rbac";
import {
  discordEnabled,
  createGuildTextChannel,
  postChannelMessage,
} from "./discord";
import { writeTicketReply, writeChatReply } from "./reply-core";

/**
 * Nxeon Discord support bridge — Phase 1 (mirror) + the reply round-trip.
 *
 * SHAPE: one plain text channel per ticket / chat conversation in a single,
 * private guild ("Nxeon Cloud"). Text channel, not a forum-with-threads:
 * forum channels cannot have PRIVATE threads in Discord's current API, and
 * since this whole guild is private anyway, "private within the guild" isn't
 * a requirement — a plain channel per ticket is simpler to create/list/delete
 * via REST and needs no thread bookkeeping. See lib/discord.ts for the REST
 * client and Ed25519 signature verification, and
 * app/api/webhooks/discord/route.ts for the Interactions Endpoint that
 * handles the Reply button + modal.
 *
 * ATTRIBUTION (2026-08-30 REWORK — real per-person linking). Every
 * Discord-originated reply used to be attributed to a single, hardcoded
 * Nxeon User.id (the `discord_reply_as_user_id` setting) — a deliberate
 * placeholder for a single-owner-only build. Now that real support staff use
 * this bridge too, `submitDiscordReply` resolves the ACTUAL Nxeon staff
 * member via `User.discordUserId` — set only through the OAuth linking flow
 * in app/api/admin/discord/authorize+callback/route.ts, which a staff member
 * completes for themselves from Settings → Integrations. See
 * `resolveDiscordReplyActor` below for the exact resolution rule.
 *
 * DESIGN DECISION: there is NO fallback to the old `discord_reply_as_user_id`
 * setting. An unlinked (or since-demoted) Discord account gets a clear,
 * visible "link your account" message back in Discord — never a silent
 * substitution to some other identity. The entire point of this rework is
 * correct PER-PERSON attribution; a quiet fallback to one shared identity
 * would partially undo that, and "reject with a clear next step" is a better
 * failure mode than "misattribute" for something that lands in an audit trail
 * and a customer-facing reply. The cost is real and intentional: the owner's
 * own account must also be linked via the new UI before their own replies
 * from Discord keep working — see this repo's rollout notes for that step.
 *
 * ACCESS CONTROL, STILL LAYERED. Discord's own guild membership + invite
 * control (who can even see these channels) plus this webhook's Ed25519
 * signature verification (nothing reaches this code without both) is the
 * outer layer, unchanged. `resolveDiscordReplyActor`'s
 * `canAccess(role, "support")` check is what stops a demoted/former staff
 * member's still-linked Discord account from continuing to reply as
 * themselves after their Nxeon role changes.
 *
 * KILL-SWITCH DISCIPLINE: every exported function below checks
 * `discordEnabled()` FIRST and returns silently if it's off, and every DB/REST
 * call is wrapped so a Discord outage or misconfiguration can NEVER throw back
 * into a ticket/chat write path — matching this codebase's established
 * best-effort third-party-integration pattern (see how `sendMail` failures are
 * handled in lib/reply-core.ts).
 *
 * SCHEMA CAVEAT: `Ticket.discordThreadId` / `ChatConversation.discordThreadId`
 * / `User.discordUserId` are NOT YET pushed to the live database (see the doc
 * comments on those fields in prisma/schema.prisma) — every read/write of
 * them here goes through an explicit `as any`/unchecked cast until a real
 * `prisma db push` + `generate` runs for this branch.
 */

const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");

// ---------------------------------------------------------------------------
// custom_id encoding — shared vocabulary between the message Reply button, the
// modal opened in response to it, and the webhook route that parses both.
// ---------------------------------------------------------------------------

export type BridgeKind = "ticket" | "chat";

function isBridgeKind(v: string): v is BridgeKind {
  return v === "ticket" || v === "chat";
}

export function replyButtonCustomId(kind: BridgeKind, id: string): string {
  return `dc_reply:${kind}:${id}`;
}

export function replyModalCustomId(kind: BridgeKind, id: string): string {
  return `dc_reply_modal:${kind}:${id}`;
}

/** Parse a `dc_reply:<kind>:<id>` or `dc_reply_modal:<kind>:<id>` custom_id. */
export function parseBridgeCustomId(
  customId: string,
): { action: "reply" | "reply_modal"; kind: BridgeKind; id: string } | null {
  const parts = customId.split(":");
  if (parts.length !== 3) return null;
  const [prefix, kindRaw, id] = parts;
  if (!id) return null;
  if (!isBridgeKind(kindRaw)) return null;
  if (prefix === "dc_reply") return { action: "reply", kind: kindRaw, id };
  if (prefix === "dc_reply_modal") return { action: "reply_modal", kind: kindRaw, id };
  return null;
}

// ---------------------------------------------------------------------------
// Ticket mirror
// ---------------------------------------------------------------------------

type TicketForChannel = { id: string; subject: string; priority: string; userId: string };

/** Create the ticket's Discord channel + post the opening context message if
 *  it doesn't have one yet; return the (existing or new) channel id. */
async function ensureTicketChannel(ticket: TicketForChannel & { discordThreadId?: string | null }): Promise<string | null> {
  const existing = (ticket as { discordThreadId?: string | null }).discordThreadId;
  if (existing) return existing;

  const user = await db.user.findUnique({ where: { id: ticket.userId }, select: { name: true, email: true } });
  const channelId = await createGuildTextChannel(
    `ticket-${ticket.id.slice(-8)}`,
    `Ticket ${ticket.id}: ${ticket.subject}`.slice(0, 1024),
  );
  if (!channelId) return null;

  await postChannelMessage(
    channelId,
    [
      "🎫 **New support ticket**",
      `**Subject:** ${ticket.subject}`,
      `**Priority:** ${ticket.priority}`,
      `**Customer:** ${user?.name ?? "?"}${user?.email ? ` (${user.email})` : ""}`,
      `**Admin:** ${APP_URL}/admin/support/${ticket.id}`,
    ].join("\n"),
  );

  await db.ticket.update({ where: { id: ticket.id }, data: { discordThreadId: channelId } as any });
  return channelId;
}

/** Mirror a brand-new ticket (called right after `db.ticket.create`). */
export async function mirrorNewTicketToDiscord(ticketId: string): Promise<void> {
  if (!(await discordEnabled())) return;
  try {
    const ticket = await db.ticket.findUnique({
      where: { id: ticketId },
      include: { messages: { orderBy: { createdAt: "asc" }, take: 1 } },
    });
    if (!ticket) return;
    const channelId = await ensureTicketChannel(ticket);
    if (!channelId) return;
    const firstMessage = ticket.messages[0];
    if (firstMessage) {
      await postChannelMessage(channelId, `👤 **Customer:** ${firstMessage.body}`, {
        replyButtonCustomId: replyButtonCustomId("ticket", ticket.id),
      });
    }
  } catch (e) {
    console.error("[discord-bridge] mirrorNewTicketToDiscord failed (non-fatal)", ticketId, e);
  }
}

/** Mirror a reply on an EXISTING ticket (staff or customer) into its channel,
 *  creating the channel first if this ticket predates the bridge (or its
 *  earlier mirror attempt failed). */
export async function mirrorTicketReplyToDiscord(ticketId: string, body: string, isStaffMessage: boolean): Promise<void> {
  if (!(await discordEnabled())) return;
  try {
    const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
    if (!ticket) return;
    const channelId = await ensureTicketChannel(ticket);
    if (!channelId) return;
    const label = isStaffMessage ? "🛟 **Staff**" : "👤 **Customer**";
    await postChannelMessage(channelId, `${label}: ${body}`, {
      replyButtonCustomId: replyButtonCustomId("ticket", ticketId),
    });
  } catch (e) {
    console.error("[discord-bridge] mirrorTicketReplyToDiscord failed (non-fatal)", ticketId, e);
  }
}

// ---------------------------------------------------------------------------
// Chat mirror
// ---------------------------------------------------------------------------

type ConvoForChannel = { id: string; name: string | null; email: string | null; userId: string | null };

async function ensureChatChannel(convo: ConvoForChannel & { discordThreadId?: string | null }): Promise<string | null> {
  const existing = (convo as { discordThreadId?: string | null }).discordThreadId;
  if (existing) return existing;

  const who = convo.name
    ? `${convo.name}${convo.email ? ` (${convo.email})` : ""}`
    : convo.email || "Anonymous visitor";
  const channelId = await createGuildTextChannel(
    `chat-${convo.id.slice(-8)}`,
    `Live chat ${convo.id}: ${who}`.slice(0, 1024),
  );
  if (!channelId) return null;

  await postChannelMessage(
    channelId,
    [
      "💬 **New live chat conversation**",
      `**Visitor:** ${who}`,
      `**Signed-in customer:** ${convo.userId ? "yes" : "no"}`,
      `**Admin inbox:** ${APP_URL}/admin/chat`,
    ].join("\n"),
  );

  await db.chatConversation.update({ where: { id: convo.id }, data: { discordThreadId: channelId } as any });
  return channelId;
}

/** Mirror one chat message (visitor, human agent, OR the AI assistant) —
 *  handles both "first message of a new conversation" (creates the channel)
 *  and "message in an existing conversation" (posts into it) via the same
 *  discordThreadId check. The "bot" case covers every message
 *  lib/kb-run.ts's AI assistant writes (its own replies, the escalation
 *  holding message, the no-agent-available fallback) — full chat history,
 *  not just human-authored messages, ends up in Discord. */
export async function mirrorChatMessageToDiscord(
  conversationId: string,
  body: string,
  sender: "visitor" | "agent" | "bot",
): Promise<void> {
  if (!(await discordEnabled())) return;
  try {
    const convo = await db.chatConversation.findUnique({ where: { id: conversationId } });
    if (!convo) return;
    const channelId = await ensureChatChannel(convo);
    if (!channelId) return;
    const label = sender === "agent" ? "🛟 **Staff**" : sender === "bot" ? "🤖 **AI Assistant**" : "👤 **Visitor**";
    await postChannelMessage(channelId, `${label}: ${body}`, {
      replyButtonCustomId: replyButtonCustomId("chat", conversationId),
    });
  } catch (e) {
    console.error("[discord-bridge] mirrorChatMessageToDiscord failed (non-fatal)", conversationId, e);
  }
}

// ---------------------------------------------------------------------------
// Reply round-trip (Discord → Nxeon) — called by the modal-submit handler in
// app/api/webhooks/discord/route.ts. Returns the text to show back in Discord
// as the interaction's visible acknowledgement message.
// ---------------------------------------------------------------------------

const NOT_LINKED_MSG =
  `⚠️ Your Discord account isn't linked to a Nxeon staff account (or it no longer has support access). ` +
  `Link it at ${APP_URL}/dashboard/settings?tab=integrations to reply from here.`;

/**
 * The whole "who is this Discord reply attributed to" decision, as a pure
 * function of the linked-user lookup — kept separate from the DB call itself
 * so it's trivially unit-testable (see test/discord-reply-attribution.test.ts)
 * without needing a live database.
 *
 * `linkedUser` is the result of `User.findUnique({ where: { discordUserId } })`
 * (or `null` if there's no `discordUserId` to look up at all — e.g. the
 * interaction payload had no resolvable Discord user id). Rejects — rather
 * than falling back to anyone — when there's no link OR the linked account no
 * longer has support access (e.g. demoted after linking). See this file's
 * top-of-file comment for why no fallback exists.
 */
export function resolveDiscordReplyActor(
  linkedUser: { id: string; role: Role } | null,
): { actorId: string } | { error: string } {
  if (!linkedUser) return { error: NOT_LINKED_MSG };
  if (!canAccess(linkedUser.role, "support")) return { error: NOT_LINKED_MSG };
  return { actorId: linkedUser.id };
}

/**
 * @param discordUserId The REAL Discord user id of whoever submitted the
 *   reply modal (from `extractInteractionUserId` on the verified interaction
 *   payload — see app/api/webhooks/discord/route.ts). `null` if it couldn't
 *   be extracted, which resolves the same as "not linked".
 */
export async function submitDiscordReply(
  kind: BridgeKind,
  id: string,
  replyText: string,
  discordUserId: string | null,
): Promise<string> {
  const text = replyText.trim();
  if (!text) return "⚠️ Empty reply — nothing sent.";

  try {
    const linkedUser = discordUserId
      ? await db.user.findUnique({ where: { discordUserId } as any, select: { id: true, role: true } })
      : null;
    const resolved = resolveDiscordReplyActor(linkedUser);
    if ("error" in resolved) {
      console.error("[discord-bridge] reply rejected — no linked staff account", { kind, id, discordUserId });
      return resolved.error;
    }
    const replyAsUserId = resolved.actorId;

    if (kind === "ticket") {
      const result = await writeTicketReply({
        actorId: replyAsUserId,
        actorIsSupportStaff: true,
        ticketId: id,
        body: text,
      });
      if (result.error) return `⚠️ ${result.error}`;
      return "✅ Reply sent to the customer.";
    }

    const result = await writeChatReply({ conversationId: id, body: text, staffId: replyAsUserId });
    if (result.error) return `⚠️ ${result.error}`;
    return "✅ Reply sent to the customer.";
  } catch (e) {
    console.error("[discord-bridge] submitDiscordReply failed", kind, id, e);
    return "⚠️ Something went wrong sending that reply — check the admin panel.";
  }
}

"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { db } from "./db";
import { realUser } from "./auth";
import { requireGrant } from "./staff-grants";
import { validateImageBytes } from "./chat-attachment";
import { checkRateLimit } from "./rate-limit";
import { markTyping, readTyping } from "./chat-typing";
import { writeChatReply } from "./reply-core";
import { mirrorChatMessageToDiscord } from "./discord-bridge";

/**
 * Staff-side live-chat actions. Every export gates on `requireGrant("liveChat")`
 * so only support staff / admins can read or write conversations. This file is
 * a "use server" module, so it may export **async functions only**.
 */

/** Shape returned to the admin inbox client component. */
type InboxAttachment = { id: string; mime: string; sizeBytes: number } | null;
type InboxMessage = {
  id: string;
  sender: string;
  body: string;
  createdAt: string;
  attachment: InboxAttachment;
};
type InboxConversation = {
  id: string;
  visitorId: string;
  userId: string | null;
  name: string | null;
  email: string | null;
  status: string;
  assignedToId: string | null;
  /** Display name of the staff member handling it, resolved from assignedToId. */
  assignedToName: string | null;
  unreadForAgent: boolean;
  lastMessageAt: string;
  createdAt: string;
  /** True while the visitor is composing (transient, self-expiring). */
  visitorTyping: boolean;
  /** Staff-set kill switch for the AI assistant on this one thread (see `toggleAiPaused`). */
  aiPaused: boolean;
  messages: InboxMessage[];
};

/**
 * Resolve staff user ids to display names in one query. Not a "use server"
 * export (it takes non-serializable args and isn't called from the client);
 * used internally to attach `assignedToName` to inbox payloads so the admin
 * thread view can label each human reply with the agent handling it.
 */
async function resolveStaffNames(
  ids: (string | null)[]
): Promise<Map<string, string>> {
  const unique = Array.from(new Set(ids.filter((v): v is string => !!v)));
  if (unique.length === 0) return new Map();
  const users = await db.user.findMany({
    where: { id: { in: unique } },
    select: { id: true, name: true },
  });
  return new Map(users.map((u) => [u.id, u.name]));
}

/** List conversations for the inbox, unread + newest first. Polled by the client. */
export async function listConversations(): Promise<InboxConversation[]> {
  await requireGrant("liveChat");
  const rows = await db.chatConversation.findMany({
    orderBy: [{ unreadForAgent: "desc" }, { lastMessageAt: "desc" }],
    take: 200,
    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
  });
  const staffNames = await resolveStaffNames(rows.map((c) => c.assignedToId));
  return rows.map((c) => ({
    id: c.id,
    visitorId: c.visitorId,
    userId: c.userId,
    name: c.name,
    email: c.email,
    status: c.status,
    assignedToId: c.assignedToId,
    assignedToName: c.assignedToId ? staffNames.get(c.assignedToId) ?? null : null,
    unreadForAgent: c.unreadForAgent,
    lastMessageAt: c.lastMessageAt.toISOString(),
    createdAt: c.createdAt.toISOString(),
    visitorTyping: readTyping(c.id).visitor,
    aiPaused: c.aiPaused,
    messages: c.messages.map((m) => ({
      id: m.id,
      sender: m.sender,
      body: m.body,
      createdAt: m.createdAt.toISOString(),
      attachment: m.attachment
        ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
        : null,
    })),
  }));
}

/** Fetch a single conversation's messages (used when opening / polling a thread). */
export async function getConversation(id: string): Promise<InboxConversation | null> {
  await requireGrant("liveChat");
  if (typeof id !== "string" || !id) return null;
  const c = await db.chatConversation.findUnique({
    where: { id },
    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
  });
  if (!c) return null;
  const staffNames = await resolveStaffNames([c.assignedToId]);
  return {
    id: c.id,
    visitorId: c.visitorId,
    userId: c.userId,
    name: c.name,
    email: c.email,
    status: c.status,
    assignedToId: c.assignedToId,
    assignedToName: c.assignedToId ? staffNames.get(c.assignedToId) ?? null : null,
    unreadForAgent: c.unreadForAgent,
    lastMessageAt: c.lastMessageAt.toISOString(),
    createdAt: c.createdAt.toISOString(),
    visitorTyping: readTyping(c.id).visitor,
    aiPaused: c.aiPaused,
    messages: c.messages.map((m) => ({
      id: m.id,
      sender: m.sender,
      body: m.body,
      createdAt: m.createdAt.toISOString(),
      attachment: m.attachment
        ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
        : null,
    })),
  };
}

/**
 * Staff reply: append an "agent" message, flag the thread unread for the user,
 * clear the agent-unread flag, and assign it to the replying staff member.
 */
export async function replyToConversation(
  id: string,
  body: string
): Promise<{ error?: string; ok?: boolean }> {
  const staff = await requireGrant("liveChat");

  const result = await writeChatReply({ conversationId: id, body, staffId: staff.id });
  if (result.error) return { error: result.error };

  // Discord bridge (Phase 1 mirror): best-effort. This reply was written from
  // the admin inbox, never from Discord (Discord-originated replies go through
  // app/api/webhooks/discord/route.ts, which calls writeChatReply directly and
  // does NOT mirror — otherwise a Discord reply would echo right back into the
  // same thread it came from).
  await mirrorChatMessageToDiscord(id, body, "agent");

  revalidatePath("/admin/chat");
  return { ok: true };
}

/**
 * Staff reply carrying an image attachment. Same authorization and side effects
 * as `replyToConversation` (requireGrant("liveChat"), notify, assign, unread) but
 * the message body may be empty and it stores a signature-verified image in
 * Postgres. All security checks (allow-list, magic-number, 5 MB cap, SVG
 * rejection) run in `validateImageBytes` — the client cannot bypass them.
 */
export async function replyWithAttachment(
  formData: FormData
): Promise<{ error?: string; ok?: boolean }> {
  const staff = await requireGrant("liveChat");

  // Throttle staff uploads defensively (shared limiter, keyed by staff id).
  const rl = checkRateLimit(`chat-upload:${staff.id}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) return { error: "Too many uploads. Please slow down." };

  const id = formData.get("conversationId");
  const rawBody = formData.get("body");
  const file = formData.get("file");

  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
  const body = typeof rawBody === "string" ? rawBody.trim().slice(0, 5000) : "";
  if (!(file instanceof File)) return { error: "No image provided." };
  if (file.size > 5 * 1024 * 1024) return { error: "Image is larger than 5 MB." };

  const convo = await db.chatConversation.findUnique({ where: { id } });
  if (!convo) return { error: "Conversation not found." };

  const bytes = Buffer.from(await file.arrayBuffer());
  const check = validateImageBytes(bytes, file.type);
  if (!check.ok) return { error: check.error };

  await db.$transaction(async (tx) => {
    const msg = await tx.chatMessage.create({
      data: { conversationId: id, sender: "agent", body },
    });
    await tx.chatAttachment.create({
      data: {
        messageId: msg.id,
        mime: check.mime,
        sizeBytes: check.bytes.length,
        data: new Uint8Array(check.bytes),
      },
    });
    await tx.chatConversation.update({
      where: { id },
      data: {
        status: "OPEN",
        unreadForUser: true,
        unreadForAgent: false,
        assignedToId: staff.id,
        lastMessageAt: new Date(),
      },
    });
  });

  if (convo.userId) {
    await db.notification
      .create({
        data: {
          userId: convo.userId,
          title: "New reply in your live chat",
          href: "/dashboard",
        },
      })
      .catch(() => {});
  }

  // Discord bridge (Phase 1 mirror): the bridge doesn't forward image bytes
  // (see lib/discord-bridge.ts), so mirror a short placeholder plus any caption.
  await mirrorChatMessageToDiscord(id, body ? `📎 ${body}` : "📎 (image attachment — view in /admin/chat)", "agent");

  revalidatePath("/admin/chat");
  return { ok: true };
}

/** Close a conversation (staff). */
export async function closeConversation(
  id: string
): Promise<{ error?: string; ok?: boolean }> {
  await requireGrant("liveChat");
  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
  const convo = await db.chatConversation.findUnique({ where: { id } });
  if (!convo) return { error: "Conversation not found." };
  await db.chatConversation.update({
    where: { id },
    data: { status: "CLOSED", unreadForAgent: false },
  });
  revalidatePath("/admin/chat");
  return { ok: true };
}

/**
 * Bulk-close every currently OPEN conversation (staff "Close all" action).
 * Returns how many were closed so the client can surface a confirmation.
 */
export async function closeAllConversations(): Promise<{ closed: number }> {
  await requireGrant("liveChat");
  const res = await db.chatConversation.updateMany({
    where: { status: "OPEN" },
    data: { status: "CLOSED", unreadForAgent: false },
  });
  revalidatePath("/admin/chat");
  return { closed: res.count };
}

/** Assign a conversation to the acting staff member and mark it read for agents. */
export async function assignConversation(
  id: string
): Promise<{ error?: string; ok?: boolean }> {
  const staff = await requireGrant("liveChat");
  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
  const convo = await db.chatConversation.findUnique({ where: { id } });
  if (!convo) return { error: "Conversation not found." };
  await db.chatConversation.update({
    where: { id },
    data: { assignedToId: staff.id, unreadForAgent: false },
  });
  revalidatePath("/admin/chat");
  return { ok: true };
}

/**
 * Record that the acting agent is composing a reply, so the visitor's widget can
 * show a "typing…" indicator. Transient and self-expiring (lib/chat-typing.ts):
 * no DB write, no revalidation — the admin inbox calls this at most once every
 * couple of seconds while the reply box has focus and content.
 */
export async function signalAgentTyping(conversationId: string): Promise<void> {
  await requireGrant("liveChat");
  if (typeof conversationId !== "string" || !conversationId) return;
  markTyping(conversationId, "agent");
}

/**
 * Flip the per-conversation AI-assistant kill switch (admin inbox "AI: On" /
 * "AI: Paused" toggle). While paused, `runAssistant` (lib/kb-run.ts) returns
 * immediately without generating a bot reply for this thread — the visitor's
 * messages still save and flag `unreadForAgent` exactly as they always do
 * (see POST /api/chat), so pausing never hides anything, it just stops the
 * AI from answering.
 */
export async function toggleAiPaused(
  id: string
): Promise<{ error?: string; ok?: boolean; aiPaused?: boolean }> {
  await requireGrant("liveChat");
  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
  const convo = await db.chatConversation.findUnique({ where: { id }, select: { aiPaused: true } });
  if (!convo) return { error: "Conversation not found." };
  const next = !convo.aiPaused;
  await db.chatConversation.update({ where: { id }, data: { aiPaused: next } });
  revalidatePath("/admin/chat");
  return { ok: true, aiPaused: next };
}

/**
 * Transfer a live-chat conversation into a support ticket (admin inbox
 * "Transfer to ticket" button).
 *
 * Ownership: `Ticket.userId` is required (see `createTicket` in
 * lib/actions-support.ts, which never creates a ticket without a real
 * `requireUser()`). A signed-in visitor's conversation already carries
 * `ChatConversation.userId` (stamped the moment they chat while logged in —
 * see POST /api/chat). An anonymous visitor has none, so we make exactly one
 * best-effort reconciliation attempt: look up a `User` by the conversation's
 * stored email — `User.email` is `@unique`, the same lookup shape used
 * elsewhere in the codebase for account matching (e.g. lib/actions.ts,
 * lib/actions-partner.ts's team-invite linking). If that still finds nothing,
 * the transfer is refused with a clear reason rather than fabricating a guest
 * ticket owner.
 *
 * Message copy: `sender: "visitor"` becomes `isStaff: false` authored by the
 * resolved customer; `sender: "agent"` becomes `isStaff: true` authored by
 * whichever staff member is assigned to the conversation (falling back to the
 * admin performing the transfer, since individual chat messages don't record
 * a per-message author — only `ChatConversation.assignedToId` does);
 * `sender: "bot"` (the AI assistant) is copied the same way, staff-side, with
 * a "[AI reply]" prefix so the ticket transcript doesn't misattribute it to a
 * human. Image attachments are NOT copied — `TicketMessage`'s attachment
 * columns are separate, actively-changing work in this tree — a
 * "[image attachment omitted]" note is left in the message body instead.
 * `createdAt` is preserved on every copied message.
 */
export async function transferChatToTicket(conversationId: string): Promise<{ error?: string }> {
  const staff = await requireGrant("liveChat");
  if (typeof conversationId !== "string" || !conversationId) return { error: "Invalid conversation." };

  const convo = await db.chatConversation.findUnique({
    where: { id: conversationId },
    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
  });
  if (!convo) return { error: "Conversation not found." };

  let matchedId = convo.userId;
  if (!matchedId && convo.email) {
    const matched = await db.user.findUnique({ where: { email: convo.email }, select: { id: true } });
    matchedId = matched?.id ?? null;
  }
  if (!matchedId) {
    return {
      error:
        `This chat isn't linked to a customer account yet — no account matches ` +
        `${convo.email ? `"${convo.email}"` : "this visitor"}. Ask them to sign in ` +
        `(or confirm their email) before transferring it to a ticket.`,
    };
  }
  const ownerId: string = matchedId;

  const firstVisitorMsg = convo.messages.find((m) => m.sender === "visitor" && m.body.trim());
  const subject = (firstVisitorMsg?.body.trim() || "Live chat conversation").slice(0, 140);

  const ticketMessages = convo.messages
    .map((m) => {
      let body = m.body?.trim() ?? "";
      if (m.attachment) body = body ? `${body}\n[image attachment omitted]` : "[image attachment omitted]";
      if (!body) return null;
      const isStaff = m.sender !== "visitor"; // "agent" and "bot" both sit on the business side
      const authorId =
        m.sender === "visitor" ? ownerId : m.sender === "agent" ? convo.assignedToId || staff.id : staff.id;
      const finalBody = m.sender === "bot" ? `[AI reply] ${body}` : body;
      return { body: finalBody.slice(0, 10000), isStaff, authorId, createdAt: m.createdAt };
    })
    .filter((m): m is NonNullable<typeof m> => m !== null);

  const TRANSFER_NOTICE =
    "This conversation was transferred to a support ticket — an agent will follow up there.";

  const ticket = await db.$transaction(async (tx) => {
    const t = await tx.ticket.create({
      data: {
        subject,
        priority: "NORMAL",
        userId: ownerId,
        messages: { create: ticketMessages },
      },
    });
    await tx.chatMessage.create({
      data: { conversationId: convo.id, sender: "bot", body: TRANSFER_NOTICE },
    });
    await tx.chatConversation.update({
      where: { id: convo.id },
      data: { status: "CLOSED", unreadForAgent: false },
    });
    return t;
  });

  await db.notification
    .createMany({
      data: (await db.user.findMany({ where: { role: "ADMIN" } })).map((a) => ({
        userId: a.id,
        title: `New ticket (from chat): ${subject}`,
        href: `/admin/support/${ticket.id}`,
      })),
    })
    .catch(() => {});

  revalidatePath("/admin/chat");
  revalidatePath("/admin/support");
  revalidatePath("/staff/chat");
  revalidatePath("/staff/support");
  // A granted EMPLOYEE transferring from the staff portal has no /admin
  // access at all — landing them on /admin/support/[id] would just bounce
  // them straight back out via that route's own gate. Route by the acting
  // staffer's role, same convention as requireAreaOrGrant's own redirects.
  redirect(staff.role === "EMPLOYEE" ? `/staff/support/${ticket.id}` : `/admin/support/${ticket.id}`);
}
/**
 * Security core for live-chat image attachments.
 *
 * Everything the upload paths (customer widget route + admin server action) and
 * the serving route agree on lives here: the allow-list, the size cap, and —
 * critically — the magic-number sniffer that validates the *real bytes* rather
 * than trusting the client-declared Content-Type. SVG is intentionally absent
 * from the allow-list AND has no binary signature, so it is rejected twice over
 * (SVG can carry <script> and would enable stored XSS if ever served).
 */

/** The only image types we accept. `image/svg+xml` is deliberately excluded. */
export const ALLOWED_IMAGE_MIME = [
  "image/png",
  "image/jpeg",
  "image/gif",
  "image/webp",
] as const;

export type AllowedImageMime = (typeof ALLOWED_IMAGE_MIME)[number];

/** Hard cap: 5 MB. Enforced server-side regardless of any client check. */
export const MAX_ATTACHMENT_BYTES = 5 * 1024 * 1024;

/** `accept` attribute value shared by the file inputs. */
export const ACCEPT_ATTR = ALLOWED_IMAGE_MIME.join(",");

export function isAllowedImageMime(mime: string): mime is AllowedImageMime {
  return (ALLOWED_IMAGE_MIME as readonly string[]).includes(mime);
}

/**
 * Detect the true image type from the leading bytes (file signature). Returns
 * the canonical MIME for a recognised, allowed image, or `null` for anything
 * else — including SVG, HTML, scripts, or a JPEG renamed to .png. Callers must
 * treat `null` as "reject".
 */
export function sniffImageMime(buf: Uint8Array): AllowedImageMime | null {
  if (buf.length < 12) return null;
  const b = buf;

  // PNG: 89 50 4E 47 0D 0A 1A 0A
  if (
    b[0] === 0x89 &&
    b[1] === 0x50 &&
    b[2] === 0x4e &&
    b[3] === 0x47 &&
    b[4] === 0x0d &&
    b[5] === 0x0a &&
    b[6] === 0x1a &&
    b[7] === 0x0a
  ) {
    return "image/png";
  }

  // JPEG: FF D8 FF
  if (b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) {
    return "image/jpeg";
  }

  // GIF: "GIF87a" / "GIF89a" — check "GIF8"
  if (b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x38) {
    return "image/gif";
  }

  // WEBP: "RIFF" .... "WEBP"
  if (
    b[0] === 0x52 &&
    b[1] === 0x49 &&
    b[2] === 0x46 &&
    b[3] === 0x46 &&
    b[8] === 0x57 &&
    b[9] === 0x45 &&
    b[10] === 0x42 &&
    b[11] === 0x50
  ) {
    return "image/webp";
  }

  return null;
}

export type AttachmentValidation =
  | { ok: true; mime: AllowedImageMime; bytes: Buffer }
  | { ok: false; error: string };

/**
 * Full server-side validation of an uploaded image. Enforces, in order:
 *  1. non-empty,
 *  2. size ≤ 5 MB,
 *  3. declared MIME (if provided) is in the allow-list and is not SVG,
 *  4. the real bytes match an allowed signature AND agree with the declared
 *     type — the authoritative check; the stored MIME is the *sniffed* one.
 */
export function validateImageBytes(
  bytes: Buffer | Uint8Array,
  declaredMime?: string | null
): AttachmentValidation {
  const buf = Buffer.isBuffer(bytes) ? bytes : Buffer.from(bytes);

  if (buf.length === 0) return { ok: false, error: "Empty file." };
  if (buf.length > MAX_ATTACHMENT_BYTES) {
    return { ok: false, error: "Image is larger than 5 MB." };
  }

  const declared = (declaredMime ?? "").split(";")[0]?.trim().toLowerCase() || null;
  if (declared) {
    if (declared === "image/svg+xml") {
      return { ok: false, error: "SVG images are not allowed." };
    }
    if (!isAllowedImageMime(declared)) {
      return { ok: false, error: "Unsupported image type." };
    }
  }

  const sniffed = sniffImageMime(buf);
  if (!sniffed) {
    return { ok: false, error: "File is not a supported image (PNG, JPEG, GIF, or WEBP)." };
  }
  if (declared && declared !== sniffed) {
    return { ok: false, error: "Image contents do not match its declared type." };
  }

  return { ok: true, mime: sniffed, bytes: buf };
}
/**
 * Transient "what the bot is doing right now" signal for the live chat, kept in
 * memory. Mirrors lib/chat-typing.ts's exact pattern — same reasons apply here:
 *
 * This is a presence hint, not durable state: it never touches the database, it
 * expires on its own after `BOT_STEP_TTL_MS`, and — exactly like
 * `lib/chat-typing.ts` / `lib/rate-limit.ts` — it lives in a module-level Map.
 * On a horizontally-scaled deployment each instance tracks independently; that
 * is acceptable for a best-effort indicator, and this app runs single-process.
 * A signal that is never refreshed simply ages out, so a crashed or hung model
 * request can never leave a stuck "Checking your billing…" label showing
 * forever — the TTL here is intentionally short (a few seconds beyond a single
 * tool round-trip) so a stalled request degrades to "no step" quickly rather
 * than lying about what's happening.
 *
 * One label per conversation: askClaudeWithTools's `onStep` hook (see
 * lib/anthropic.ts) fires right before each tool call, and lib/kb-llm.ts maps
 * the tool name to a short human-readable label and calls `setBotStep`. The
 * poll endpoint (app/api/chat/route.ts) reads it back with `readBotStep` so
 * <ChatWidget/> can show live progress instead of a static "thinking" pulse.
 */

export const BOT_STEP_TTL_MS = 9000;

type Signal = { label: string; at: number };

const local = new Map<string, Signal>();

// Persist across HMR / route reloads in dev so a signal isn't lost on every edit.
const globalForBotStep = globalThis as unknown as { __nxeonChatBotStep?: Map<string, Signal> };
const store: Map<string, Signal> = globalForBotStep.__nxeonChatBotStep ?? local;
if (process.env.NODE_ENV !== "production") globalForBotStep.__nxeonChatBotStep = store;

/**
 * Is a timestamp still "live" — i.e. within `ttl` of `now`? Pure and total:
 * an absent/zero/future-garbage timestamp is never active. Exported for tests,
 * same shape as chat-typing.ts's `isTypingActive`.
 */
export function isStepActive(at: number | undefined, now: number = Date.now(), ttl: number = BOT_STEP_TTL_MS): boolean {
  return typeof at === "number" && at > 0 && now - at >= 0 && now - at < ttl;
}

/** Record the bot's current step label for `conversationId`. */
export function setBotStep(conversationId: string, label: string, now: number = Date.now()): void {
  if (!conversationId || !label) return;
  store.set(conversationId, { label, at: now });
  prune(now);
}

/** Current step label for a conversation, or null once it's expired/absent. */
export function readBotStep(conversationId: string, now: number = Date.now()): string | null {
  const cur = store.get(conversationId);
  if (!cur) return null;
  return isStepActive(cur.at, now) ? cur.label : null;
}

/** Immediately clear the step for a conversation — called once a turn finishes
 *  (success or failure) so a stale label can never bleed into the next turn's
 *  pre-tool-call gap. */
export function clearBotStep(conversationId: string): void {
  if (!conversationId) return;
  store.delete(conversationId);
}

/** Drop conversations whose signal has expired, bounding the Map. */
function prune(now: number): void {
  for (const [id, sig] of store) {
    if (!isStepActive(sig.at, now)) store.delete(id);
  }
}

/** Test-only: clear all signals so suites don't leak state into each other. */
export function _resetBotStep(): void {
  store.clear();
}
/**
 * Transient "typing…" signals for the live chat, kept in memory.
 *
 * This is a presence hint, not durable state: it never touches the database, it
 * expires on its own after `TYPING_TTL_MS`, and — exactly like `lib/rate-limit.ts`
 * — it lives in a module-level Map. On a horizontally-scaled deployment each
 * instance tracks independently; that is acceptable for a best-effort indicator,
 * and this app runs single-process. A signal that is never refreshed simply
 * ages out, so a crashed tab or a dropped connection can never leave a stuck
 * "typing" showing forever.
 *
 * Two directions per conversation:
 *   - visitor typing → surfaced to the agent (admin inbox)
 *   - agent typing   → surfaced to the visitor (ChatWidget)
 */

export const TYPING_TTL_MS = 6000;

export type TypingWho = "visitor" | "agent";
type Signal = { visitorAt?: number; agentAt?: number };

const local = new Map<string, Signal>();

// Persist across HMR / route reloads in dev so a signal isn't lost on every edit.
const globalForTyping = globalThis as unknown as { __nxeonChatTyping?: Map<string, Signal> };
const store: Map<string, Signal> = globalForTyping.__nxeonChatTyping ?? local;
if (process.env.NODE_ENV !== "production") globalForTyping.__nxeonChatTyping = store;

/**
 * Is a timestamp still "live" — i.e. within `ttl` of `now`? Pure and total:
 * an absent/zero/future-garbage timestamp is never active. This is the single
 * predicate the whole expiry behaviour is built on, so it is exported for tests.
 */
export function isTypingActive(lastAt: number | undefined, now: number = Date.now(), ttl: number = TYPING_TTL_MS): boolean {
  return typeof lastAt === "number" && lastAt > 0 && now - lastAt >= 0 && now - lastAt < ttl;
}

/** Record that `who` is currently typing in `conversationId`. */
export function markTyping(conversationId: string, who: TypingWho, now: number = Date.now()): void {
  if (!conversationId) return;
  const cur = store.get(conversationId) ?? {};
  if (who === "visitor") cur.visitorAt = now;
  else cur.agentAt = now;
  store.set(conversationId, cur);
  prune(now);
}

/** Current typing state for a conversation, after expiry is applied. */
export function readTyping(conversationId: string, now: number = Date.now()): { visitor: boolean; agent: boolean } {
  const cur = store.get(conversationId);
  if (!cur) return { visitor: false, agent: false };
  return {
    visitor: isTypingActive(cur.visitorAt, now),
    agent: isTypingActive(cur.agentAt, now),
  };
}

/** Drop conversations whose signals have all expired, bounding the Map. */
function prune(now: number): void {
  for (const [id, sig] of store) {
    if (!isTypingActive(sig.visitorAt, now) && !isTypingActive(sig.agentAt, now)) {
      store.delete(id);
    }
  }
}

/** Test-only: clear all signals so suites don't leak state into each other. */
export function _resetTyping(): void {
  store.clear();
}

