import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
import { readTyping } from "@/lib/chat-typing";
import { readBotStep } from "@/lib/chat-bot-step";
import { mirrorChatMessageToDiscord } from "@/lib/discord-bridge";

export const runtime = "nodejs";

/**
 * Public live-chat endpoint used by <ChatWidget/>.
 *
 * POST /api/chat  — start or continue a conversation for a visitorId.
 * GET  /api/chat?visitorId=…  — poll the visitor's open conversation.
 *
 * Everything is scoped strictly by the client-supplied `visitorId`; we never
 * return another visitor's data. Signed-in customers additionally get their
 * `userId` stamped on the conversation. Unauthenticated + write-heavy, so the
 * POST path is rate-limited per IP.
 */

function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

type AttachmentRow = { id: string; mime: string; sizeBytes: number } | null;

function serialize(convo: {
  id: string;
  status: string;
  name: string | null;
  email: string | null;
  messages: {
    id: string;
    sender: string;
    body: string;
    cardsJson?: string | null;
    createdAt: Date;
    attachment?: AttachmentRow;
  }[];
}) {
  return {
    conversation: {
      id: convo.id,
      status: convo.status,
      name: convo.name,
      email: convo.email,
    },
    messages: convo.messages.map((m) => {
      let cards: unknown = null;
      if (m.cardsJson) {
        try {
          cards = JSON.parse(m.cardsJson);
        } catch {
          cards = null;
        }
      }
      return {
        id: m.id,
        sender: m.sender,
        body: m.body,
        createdAt: m.createdAt.toISOString(),
        cards,
        attachment: m.attachment
          ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
          : null,
      };
    }),
  };
}

export async function POST(req: Request) {
  const rl = checkRateLimit(`chat:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "Too many messages. Please slow down." },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  const raw = (await req.json().catch(() => ({}))) as Record<string, unknown>;
  const visitorId = clip(raw.visitorId, 100);
  const conversationId = clip(raw.conversationId, 40);
  const body = clip(raw.body, 5000);
  const name = clip(raw.name, 120);
  const email = clip(raw.email, 200);

  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
  if (!body) return NextResponse.json({ error: "Message cannot be empty." }, { status: 400 });

  const user = await currentUser();
  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
    user?.id ? [{ userId: user.id }] : [],
  );

  // If the client names a conversation it owns, continue it (resuming past
  // history, reopening if it was closed). Otherwise start a brand-new one — we
  // no longer auto-resume the latest, so returning gives a fresh chat while old
  // threads stay available in the history list.
  let convo = conversationId
    ? await db.chatConversation.findFirst({
        where: { id: conversationId, OR: ownedBy },
        select: { id: true, name: true, email: true },
      })
    : null;

  if (!convo) {
    // Anonymous (not signed in) visitors must give a name + valid email before
    // starting. Signed-in customers already have both, so they're never asked.
    if (!user) {
      const nm = name ?? null;
      const em = email ?? null;
      if (!nm || !em || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)) {
        return NextResponse.json(
          { error: "Please add your name and a valid email to start the chat.", needIdentity: true },
          { status: 400 },
        );
      }
    }
    convo = await db.chatConversation.create({
      data: {
        visitorId,
        userId: user?.id ?? null,
        name: name ?? user?.name ?? null,
        email: email ?? user?.email ?? null,
      },
      select: { id: true, name: true, email: true },
    });
  }

  await db.$transaction([
    db.chatMessage.create({
      data: { conversationId: convo.id, sender: "visitor", body },
    }),
    db.chatConversation.update({
      where: { id: convo.id },
      data: {
        status: "OPEN", // reopen if the visitor is resuming a closed thread
        unreadForAgent: true,
        lastMessageAt: new Date(),
        // Backfill identity / link account if it arrives after creation.
        ...(user?.id ? { userId: user.id } : {}),
        ...(name && !convo.name ? { name } : {}),
        ...(email && !convo.email ? { email } : {}),
      },
    }),
  ]);

  // Discord bridge (Phase 1 mirror): best-effort, never blocks the visitor's
  // message — creates the guild channel on the visitor's FIRST message, posts
  // into the existing channel on every message after — see
  // lib/discord-bridge.ts's mirrorChatMessageToDiscord.
  await mirrorChatMessageToDiscord(convo.id, body, "visitor");

  // AI assistant + human-handoff orchestration (see lib/kb-run.ts). Best-effort
  // and fully wrapped: it must NEVER break live chat, and it stays silent once a
  // human has engaged.
  try {
    const { runAssistant } = await import("@/lib/kb-run");
    await runAssistant({ conversationId: convo.id, visitorId, currentBody: body });
  } catch {
    /* assistant is non-essential — never fail the visitor's message on it */
  }

  const full = await db.chatConversation.findUnique({
    where: { id: convo.id },
    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
  });
  return NextResponse.json(serialize(full!), { headers: NO_STORE_HEADERS });
}

export async function GET(req: Request) {
  const url = new URL(req.url);
  const visitorId = clip(url.searchParams.get("visitorId"), 100);
  const conversationId = clip(url.searchParams.get("conversationId"), 40);
  if (!visitorId) {
    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
  }

  const user = await currentUser();
  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
    user?.id ? [{ userId: user.id }] : [],
  );

  // Poll a specific conversation when named (scoped to the visitor/user), else
  // the most recent open thread for back-compat.
  let convo = conversationId
    ? await db.chatConversation.findFirst({
        where: { id: conversationId, OR: ownedBy },
        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
      })
    : await db.chatConversation.findFirst({
        where: { visitorId, status: "OPEN" },
        orderBy: { lastMessageAt: "desc" },
        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
      });

  if (!convo) {
    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
  }

  // If the bot is waiting on a live agent, let the poll drive the handoff window:
  // post the "no agents available" fallback once it elapses, then refresh so the
  // visitor sees it on this same poll rather than the next one.
  if (convo.botEscalatedAt) {
    try {
      const { checkEscalationTimeout } = await import("@/lib/kb-run");
      await checkEscalationTimeout(convo.id);
      const refreshed = await db.chatConversation.findFirst({
        where: { id: convo.id },
        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
      });
      if (refreshed) convo = refreshed;
    } catch {
      /* non-essential */
    }
  }

  // Reading the thread clears the visitor-facing unread flag.
  if (convo.unreadForUser) {
    await db.chatConversation
      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
      .catch(() => {});
  }

  // The whole support transcript, plus the name/email the visitor gave. The
  // `?visitorId=` in the URL is the ONLY thing scoping it, which makes the URL
  // itself the secret — precisely the shape a shared cache must never store.
  //
  // `typing.agent` tells the widget whether a support agent is composing a reply
  // right now; it self-expires, so a stale poll can only ever under-report.
  // `botStep` is the AI agent's current live "thinking" step (e.g. "Checking
  // your billing…"), sourced from lib/chat-bot-step.ts; it self-expires too, so
  // a stalled/crashed model call can never leave a stuck label on screen.
  return NextResponse.json(
    { ...serialize(convo), typing: { agent: readTyping(convo.id).agent }, botStep: readBotStep(convo.id) },
    { headers: NO_STORE_HEADERS },
  );
}
