import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const runtime = "nodejs";

/**
 * GET /api/chat/list?visitorId=… — the visitor's past conversations, newest
 * first, so the widget can show a "previous chats" list they can resume.
 *
 * Ownership: a conversation is theirs if the `visitorId` matches, OR (when
 * signed in) the conversation's `userId` matches the current user — so a
 * logged-in customer sees their threads across browsers/devices, plus any
 * anonymous chats started in this browser before they logged in.
 */

function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

export async function GET(req: Request) {
  const url = new URL(req.url);
  const visitorId = clip(url.searchParams.get("visitorId"), 100);
  const user = await currentUser();

  if (!visitorId && !user) {
    return NextResponse.json({ conversations: [] }, { headers: NO_STORE_HEADERS });
  }

  const or: Array<Record<string, unknown>> = [];
  if (visitorId) or.push({ visitorId });
  if (user?.id) or.push({ userId: user.id });

  const rows = await db.chatConversation.findMany({
    where: { OR: or },
    orderBy: { lastMessageAt: "desc" },
    take: 20,
    select: {
      id: true,
      status: true,
      lastMessageAt: true,
      unreadForUser: true,
      // First message → a human-readable title; last message → a preview line.
      messages: {
        orderBy: { createdAt: "asc" },
        take: 1,
        select: { body: true },
      },
    },
  });

  // Last message per conversation for the preview (cheap: one grouped query).
  const ids = rows.map((r) => r.id);
  const lasts = ids.length
    ? await db.chatMessage.findMany({
        where: { conversationId: { in: ids } },
        orderBy: { createdAt: "desc" },
        distinct: ["conversationId"],
        select: { conversationId: true, body: true, sender: true },
      })
    : [];
  const lastBy = new Map(lasts.map((m) => [m.conversationId, m]));

  const conversations = rows.map((r) => {
    const first = r.messages[0]?.body?.trim() || "";
    const last = lastBy.get(r.id);
    const title = first ? first.slice(0, 60) : "New conversation";
    const preview = last?.body?.trim()
      ? `${last.sender === "visitor" ? "You: " : ""}${last.body.trim().slice(0, 80)}`
      : "";
    return {
      id: r.id,
      title,
      preview,
      status: r.status,
      unread: r.unreadForUser,
      lastMessageAt: r.lastMessageAt.toISOString(),
    };
  });

  return NextResponse.json({ conversations }, { headers: NO_STORE_HEADERS });
}
