const KINDS = ["BUG", "FEATURE"] as const;
const STATUSES = ["NEW", "PLANNED", "IN_PROGRESS", "DONE", "DECLINED"] as const;

export type Kind = (typeof KINDS)[number];
export type FeedbackStatus = (typeof STATUSES)[number];

/**
 * Customer-facing: file a bug report or feature request. Called directly (with
 * positional args) from the floating FeedbackWidget and the dashboard form.
 */
export async function submitFeedback(
  kind: string,
  title: string,
  body: string,
  url: string
): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();

  const parsed = z
    .object({
      kind: z.enum(KINDS),
      title: z.string().trim().min(3).max(150),
      body: z.string().trim().min(5).max(5000),
      url: z.string().trim().max(500).optional(),
    })
    .safeParse({ kind, title, body, url });

  if (!parsed.success) {
    return { error: "Please add a title (3+ chars) and a description (5+ chars)." };
  }

  await db.feedback.create({
    data: {
      userId: user.id,
      kind: parsed.data.kind,
      title: parsed.data.title,
      body: parsed.data.body,
      url: parsed.data.url && parsed.data.url.length > 0 ? parsed.data.url : null,
    },
  });

  // Ping staff so triage sees it.
  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
  if (admins.length > 0) {
    await db.notification.createMany({
      data: admins.map((a) => ({
        userId: a.id,
        title: `New ${parsed.data.kind === "BUG" ? "bug report" : "feature request"}: ${parsed.data.title}`,
        href: `/admin/feedback`,
      })),
    });
  }

  revalidatePath("/dashboard/feedback");
  revalidatePath("/admin/feedback");
  return { ok: true };
}

/** Admin triage: change status and/or set an internal note. */
export async function adminUpdateFeedback(
  id: string,
  status: string,
  adminNote: string
): Promise<{ error?: string; ok?: boolean }> {
  await requireArea("support");

  const parsed = z
    .object({
      id: z.string().min(1),
      status: z.enum(STATUSES),
      adminNote: z.string().trim().max(2000),
    })
    .safeParse({ id, status, adminNote });

  if (!parsed.success) return { error: "Invalid status or note." };

  const existing = await db.feedback.findUnique({ where: { id: parsed.data.id } });
  if (!existing) return { error: "Feedback not found." };

  await db.feedback.update({
    where: { id: parsed.data.id },
    data: {
      status: parsed.data.status,
      adminNote: parsed.data.adminNote.length > 0 ? parsed.data.adminNote : null,
    },
  });

  // Let the reporter know their item moved forward.
  if (existing.userId && parsed.data.status !== existing.status) {
    await db.notification.create({
      data: {
        userId: existing.userId,
        title: `Your ${existing.kind === "BUG" ? "bug report" : "feature request"} is now ${parsed.data.status.replace(/_/g, " ").toLowerCase()}`,
        href: `/dashboard/feedback`,
      },
    });
  }

  revalidatePath("/dashboard/feedback");
  revalidatePath("/admin/feedback");
  return { ok: true };
}

/** Admin listing with optional kind/status filter. */
export async function adminListFeedback(filter?: { kind?: string; status?: string }) {
  await requireArea("support");
  const where: { kind?: string; status?: string } = {};
  if (filter?.kind && (KINDS as readonly string[]).includes(filter.kind)) where.kind = filter.kind;
  if (filter?.status && (STATUSES as readonly string[]).includes(filter.status)) where.status = filter.status;
  return db.feedback.findMany({
    where,
    include: { user: { select: { email: true, name: true } } },
    orderBy: { createdAt: "desc" },
  });
}
