const FILTERS = [
  { value: "", label: "All" },
  { value: "GAME", label: "Game Servers" },
  { value: "VPS", label: "VPS" },
  { value: "HOSTING", label: "Hosting" },
  { value: "MAIL", label: "Mail" },
];

/**
 * Full "What's New" feed: all published announcements in a timeline layout.
 * Unseen ones get a "New" badge. When an unseen announcement scrolls into
 * view (or is present on initial render), it is marked as seen after a short
 * delay so the badge lingers long enough to be noticed.
 */
export function WhatsNew() {
  const [entries, setEntries] = useState<WhatsNewEntry[]>([]);
  const [filter, setFilter] = useState("");
  const [loading, setLoading] = useState(true);
  const [, startTransition] = useTransition();

  const load = useCallback((serviceFilter: string) => {
    setLoading(true);
    getWhatsNew(serviceFilter || undefined)
      .then(setEntries)
      .catch(() => setEntries([]))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    load(filter);
  }, [filter, load]);

  function handleFilterChange(val: string) {
    setFilter(val);
  }

  /** Mark an announcement as seen (optimistic local update + server write). */
  function handleSeen(id: string) {
    setEntries((prev) =>
      prev.map((e) => (e.id === id ? { ...e, seen: true } : e)),
    );
    startTransition(async () => {
      try {
        await markAnnouncementSeen(id);
      } catch {
        /* best-effort */
      }
    });
  }

  return (
    <div className="space-y-6">
      {/* Filter tabs */}
      <div className="flex flex-wrap gap-2">
        {FILTERS.map((f) => (
          <button
            key={f.value}
            onClick={() => handleFilterChange(f.value)}
            className={`rounded-lg border px-3 py-1.5 text-sm font-medium transition-colors ${
