              fill="none"
              stroke="#8a70fb"
              strokeWidth="1.5"
            >
              <path d="M11 3l1.8 4.9L17.7 9.7l-4.9 1.8L11 16.4l-1.8-4.9L4.3 9.7l4.9-1.8zM18 14.5l.85 2.15L21 17.5l-2.15.85L18 20.5l-.85-2.15L15 17.5l2.15-.85z" />
            </svg>
          </div>
          <p className="text-sm font-medium text-white">No updates yet</p>
          <p className="mt-1 text-sm text-slate-400">
