function AnnouncementCard({
  entry,
  onSeen,
}: {
  entry: WhatsNewEntry;
  onSeen: (id: string) => void;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const markedRef = useRef(false);

  useEffect(() => {
    if (entry.seen || markedRef.current) return;
    const el = ref.current;
    if (!el) return;

    const observer = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting && !markedRef.current) {
          markedRef.current = true;
          // Short delay so the "New" badge is visible before it disappears.
          const timer = setTimeout(() => onSeen(entry.id), 2000);
          observer.disconnect();
          return () => clearTimeout(timer);
        }
      },
      { threshold: 0.5 },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [entry.id, entry.seen, onSeen]);

  const date = new Date(entry.publishedAt);
  const formatted = date.toLocaleDateString("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  });

  return (
    <div
      ref={ref}
      className="card relative overflow-hidden border border-white/[0.06]"
    >
      {/* Timeline dot + date row */}
      <div className="flex items-center gap-3 px-5 pt-5">
        <span className="h-2.5 w-2.5 shrink-0 rounded-full bg-brand-500" />
        <span className="text-xs text-slate-500">{formatted}</span>
        {!entry.seen && (
          <span className="inline-flex items-center rounded-full border border-brand-400/40 bg-brand-500/15 px-2 py-0.5 text-[10px] font-semibold text-brand-300">
            New
          </span>
        )}
        {entry.serviceTypes.length > 0 && (
          <div className="ml-auto flex gap-1.5">
            {entry.serviceTypes.map((t) => (
              <span
                key={t}
                className="rounded border border-white/10 bg-white/[0.05] px-1.5 py-0.5 text-[10px] text-slate-400"
              >
                {t}
              </span>
            ))}
          </div>
        )}
      </div>

      {/* Title */}
      <h3 className="mt-3 px-5 text-base font-bold text-white">
        {entry.title}
      </h3>

      {/* Body */}
      <div className="mt-2 px-5 pb-5">
        {entry.gameFamilies.length > 0 && (
          <div className="mb-4">
            {entry.gameFamilies.length > 1 && (
              <p className="mb-2 text-[11px] font-medium uppercase tracking-wide text-slate-500">
                Games covered in this update
              </p>
            )}
            <div className={`grid gap-2 ${entry.gameFamilies.length === 1 ? "grid-cols-3 sm:grid-cols-4" : "grid-cols-4 sm:grid-cols-6"}`}>
              {entry.gameFamilies.map((g) => (
                <div key={g} className="overflow-hidden rounded-lg border border-white/10">
                  <GameCoverTile family={g} name={GAME_DISPLAY[g as GameFamily]?.name ?? g} />
                  <p className="truncate bg-black/40 px-1.5 py-1 text-center text-[10px] font-medium text-slate-200">
                    {GAME_DISPLAY[g as GameFamily]?.name ?? g}
                  </p>
                </div>
              ))}
            </div>
          </div>
        )}
        <div dangerouslySetInnerHTML={{ __html: renderMarkdown(entry.body) }} />
        {entry.screenshotUrl && (
          <div className="mt-4">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={entry.screenshotUrl}
              alt={`Screenshot for ${entry.title}`}
              className="w-full rounded-xl border border-white/10 shadow-lg shadow-black/20"
              loading="lazy"
            />
          </div>
        )}
      </div>
    </div>
  );
}
