"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";
import { GAME_FAMILIES, type GameFamily } from "./games";

/**
 * Update Announcements — service-specific release notes pushed to customers.
 *
 * Admin creates a DRAFT, then explicitly publishes it (the approval gate).
 * Customers see a popup on first login after publish and a persistent
 * "What's New" feed. `serviceTypes` scopes visibility: a user only sees
 * announcements for services they actually have; empty = everyone.
 *
 * Admin actions are area-gated ("platform"). Customer actions self-auth via
 * `requireUser()` and only ever touch that user's own rows.
 */

const SERVICE_TYPES = ["GAME", "VPS", "HOSTING", "MAIL"] as const;
export type ServiceType = (typeof SERVICE_TYPES)[number];

// ---------- Admin ----------

export async function listAnnouncements() {
  await requireArea("platform");
  return db.updateAnnouncement.findMany({
    orderBy: { createdAt: "desc" },
    take: 200,
    include: { _count: { select: { seenBy: true } } },
  });
}

export async function createAnnouncement(input: {
  title: string;
  body: string;
  serviceTypes: string[];
  gameFamilies?: string[];
  screenshotUrl?: string | null;
}): Promise<{ error?: string; ok?: boolean }> {
  await requireArea("platform");
  const title = String(input.title ?? "").trim();
  if (!title) return { error: "Enter a title." };
  const body = String(input.body ?? "").trim();
  if (!body) return { error: "Enter a body." };

  // Validate service types — only allow known values.
  const serviceTypes = (input.serviceTypes ?? []).filter((t) =>
    (SERVICE_TYPES as readonly string[]).includes(t),
  );

  // Game families only make sense when the update is GAME-scoped. Validate
  // against the real game family list so a typo can never silently no-op.
  const gameFamilies = serviceTypes.includes("GAME")
    ? (input.gameFamilies ?? []).filter((g) => (GAME_FAMILIES as readonly string[]).includes(g))
    : [];

  // Screenshot must be a relative path, not an external URL.
  let screenshotUrl: string | null = null;
  if (input.screenshotUrl) {
    const u = input.screenshotUrl.trim();
    if (u && !u.startsWith("/")) return { error: "Screenshot must be a relative path (e.g. /uploads/announcements/img.png)." };
    screenshotUrl = u || null;
  }

  await db.updateAnnouncement.create({
    data: {
      title: title.slice(0, 200),
      body: body.slice(0, 10_000),
      serviceTypes,
      gameFamilies,
      screenshotUrl,
      status: "DRAFT",
    },
  });
  revalidatePath("/admin/announcements");
  return { ok: true };
}

export async function publishAnnouncement(id: string): Promise<void> {
  await requireArea("platform");
  await db.updateAnnouncement.update({
    where: { id },
    data: { status: "PUBLISHED", publishedAt: new Date() },
  });
  revalidatePath("/admin/announcements");
}

export async function unpublishAnnouncement(id: string): Promise<void> {
  await requireArea("platform");
  await db.updateAnnouncement.update({
    where: { id },
    data: { status: "DRAFT" },
  });
  revalidatePath("/admin/announcements");
}

export async function deleteAnnouncement(id: string): Promise<void> {
  await requireArea("platform");
  await db.updateAnnouncement.delete({ where: { id } }).catch(() => undefined);
  revalidatePath("/admin/announcements");
}

// ---------- Customer ----------

/** Determine which service types the current user has active services for. */
async function getUserServiceTypes(userId: string): Promise<string[]> {
  const [servers, hosting] = await Promise.all([
    db.server.findFirst({ where: { userId } }),
    db.hostingAccount.findFirst({ where: { userId } }),
  ]);
  const types: string[] = [];
  if (servers) {
    const hasGame = await db.server.findFirst({
      where: { userId, gamePlanId: { not: null } },
    });
    if (hasGame) types.push("GAME");
    const hasVps = await db.server.findFirst({
      where: { userId, gamePlanId: null },
    });
    if (hasVps) types.push("VPS");
  }
  if (hosting) types.push("HOSTING");
  // MAIL: anyone with a hosting account potentially has mail; we keep it
  // simple and include MAIL for hosting customers too.
  if (hosting) types.push("MAIL");
  return types;
}

/**
 * PUBLISHED announcements the current user hasn't seen, filtered by service
 * types matching their actual services. An announcement with empty
 * serviceTypes[] is shown to everyone.
 */
export async function getUnseenAnnouncements() {
  const user = await requireUser();
  const userServices = await getUserServiceTypes(user.id);

  const announcements = await db.updateAnnouncement.findMany({
    where: {
      status: "PUBLISHED",
      seenBy: { none: { userId: user.id } },
    },
    orderBy: { publishedAt: "desc" },
  });

  // Filter by service type: show if announcement has no serviceTypes (global)
  // or if at least one of the user's service types matches.
  return announcements.filter(
    (a) =>
      a.serviceTypes.length === 0 ||
      a.serviceTypes.some((t) => userServices.includes(t)),
  );
}

/** Mark an announcement as seen by the current user. Upserts to stay idempotent. */
export async function markAnnouncementSeen(announcementId: string): Promise<void> {
  const user = await requireUser();
  await db.userAnnouncementSeen.upsert({
    where: {
      userId_announcementId: { userId: user.id, announcementId },
    },
    create: { userId: user.id, announcementId },
    update: {},
  });
}

export type WhatsNewEntry = {
  id: string;
  title: string;
  body: string;
  serviceTypes: string[];
  gameFamilies: string[];
  screenshotUrl: string | null;
  publishedAt: string; // ISO string for serialization
  seen: boolean;
};

/**
 * All PUBLISHED announcements, optionally filtered by service type, ordered
 * by publishedAt desc, with a `seen` boolean flag for the current user.
 */
export async function getWhatsNew(
  serviceFilter?: string,
): Promise<WhatsNewEntry[]> {
  const user = await requireUser();

  const where: Record<string, unknown> = { status: "PUBLISHED" };
  if (serviceFilter && (SERVICE_TYPES as readonly string[]).includes(serviceFilter)) {
    where.serviceTypes = { has: serviceFilter };
  }

  const announcements = await db.updateAnnouncement.findMany({
    where,
    orderBy: { publishedAt: "desc" },
    include: {
      seenBy: {
        where: { userId: user.id },
        take: 1,
      },
    },
  });

  return announcements.map((a) => ({
    id: a.id,
    title: a.title,
    body: a.body,
    serviceTypes: a.serviceTypes,
    gameFamilies: a.gameFamilies,
    screenshotUrl: a.screenshotUrl,
    publishedAt: (a.publishedAt ?? a.createdAt).toISOString(),
    seen: a.seenBy.length > 0,
  }));
}
