/**
 * Friendly conversation layer for the chat assistant — bounded on purpose.
 *
 * These are the ONLY non-knowledge-base things the bot will say on its own:
 * greetings, thanks, goodbyes, and "who/what are you". Everything substantive
 * still goes through knowledge-base retrieval (lib/kb.ts), and anything it can't
 * confidently answer stays silent for a human. Keeping small talk to a short,
 * explicit rule set is what stops the bot from bluffing.
 *
 * Patterns are ordered; the first match wins. Use \b anchors so a phrase like
 * "how is your uptime" is NOT mistaken for "how are you".
 */
type Rule = { re: RegExp; reply: string };

// Only the cheap CLOSERS stay local (they don't need grounding OR personalizing).
// Greetings / "who are you" / "how are you" / "what can you do" now flow to the
// LLM so the reply is personalized and conversational (greeted by name); when no
// key is configured, kb.ts uses greetingReply() as a friendly canned fallback.
const RULES: Rule[] = [
  {
    re: /\b(thank(s| you)|thx|ty|much appreciated|appreciate it|cheers)\b/i,
    reply: "You're welcome! Anything else I can help with?",
  },
  {
    re: /^\s*(ok(ay)?|kk?|cool|great|nice|awesome|perfect|sweet|got it|sounds good|will do|makes sense)\s*[.!]*\s*$/i,
    reply: "Glad that helps! Anything else you'd like to know?",
  },
  {
    re: /\b(bye|goodbye|see\s+ya|see\s+you|later|good\s*night|gotta\s+go|that'?s\s+(all|it)|nothing\s+else|i'?m\s+good)\b/i,
    reply: "Thanks for stopping by! Message us here anytime — have a great day.",
  },
];

/** A friendly reply for thanks / affirmations / goodbyes, or null when the
 *  message is a greeting or something substantive (both handled elsewhere). */
export function smalltalk(text: string): string | null {
  const t = text.trim();
  if (!t) return null;
  for (const r of RULES) if (r.re.test(t)) return r.reply;
  return null;
}

/** Greetings and "who/what are you" — routed to the LLM for a personalized,
 *  conversational reply (greeted by name); a canned personalized greeting is
 *  used only when no LLM is available. */
export function greetingIntent(text: string): boolean {
  const t = text.trim();
  return (
    /^\s*(hi+|hey+|hello+|yo+|howdy|hiya|heya|greetings|sup|good\s+(morning|afternoon|evening|day))\b/i.test(t) ||
    /\bhow('?s| is| are|'?re| are ya)\s+(you|it going|things|things going|everything|ya doing)\b/i.test(t) ||
    /\b(who\s+are\s+you|what\s+are\s+you|are\s+you\s+(a\s+)?(bot|human|robot|ai|real|person)|is\s+this\s+a\s+bot|what\s+can\s+you\s+(do|help))\b/i.test(t)
  );
}

/** Personalized canned greeting used only when Claude isn't available. */
export function greetingReply(name?: string | null): string {
  const who = name && name.trim() ? ` ${name.trim()}` : " there";
  return `Hey${who}! 👋 Good to have you here — I can help with anything from picking a plan to a question about your account or something technical. What are you working on today?`;
}
