  /** Refund or write-off issued against the account. */
  refund: "CRITICAL",

  // ---- ACCOUNT: informational transactional. Email opt-out honoured. -------
  welcome: "ACCOUNT",
  /** Receipt for a payment that SUCCEEDED. (A failure is `payment_failed`.) */
  receipt: "ACCOUNT",
  invoice: "ACCOUNT",
  /** Deploy / reinstall / migration finished successfully. */
  provision_done: "ACCOUNT",
  /** Backup taken, app installed, certificate issued, volume attached, … */
  job_done: "ACCOUNT",
  /** Domain registered / renewed / transferred. */
  domain_activity: "ACCOUNT",
  support_reply: "ACCOUNT",
  referral_bonus: "ACCOUNT",

