import type { BlogPost } from "@prisma/client";

/* ----------------------------------------------------------------------------
 * Help center / knowledge base helpers.
 *
 * The help center is a docs-style re-presentation of the existing published
 * BlogPost content: posts are grouped by their `category` into KB sections.
 * These helpers are plain (non-server-action) functions consumed by the
 * server component at app/help/page.tsx.
 * ------------------------------------------------------------------------- */

export type HelpCategory = {
  /** Canonical category name as stored on BlogPost.category. */
  name: string;
  /** URL slug used by the ?c= filter query param. */
  slug: string;
  /** Emoji used in the category grid tiles. */
  emoji: string;
  /** One-line human description of what the section covers. */
  blurb: string;
};

/**
 * Curated metadata for the categories we know exist in the content set. Any
 * post whose category is not listed here still gets a section via a sensible
 * fallback (see `categoryMeta`), so the KB never drops content.
 */
const CATEGORY_META: Omit<HelpCategory, "slug">[] = [
  { name: "Gaming", emoji: "🎮", blurb: "Minecraft, Rust, and other game-server setup and tuning." },
  { name: "VPS", emoji: "🖥️", blurb: "Provisioning, managing, and getting the most from your VPS." },
  { name: "Tutorials", emoji: "📘", blurb: "Step-by-step walkthroughs for common hosting tasks." },
  { name: "Security", emoji: "🛡️", blurb: "Hardening servers, firewalls, 2FA, and staying safe." },
  { name: "Control Panels", emoji: "🎛️", blurb: "Working with panels and dashboards to run your services." },
  { name: "Domains", emoji: "🌐", blurb: "Registering, pointing, and managing your domain names." },
  { name: "Hosting", emoji: "☁️", blurb: "Choosing and running the right hosting for your project." },
  { name: "Guides", emoji: "📗", blurb: "Practical, no-fluff guides for people who self-host." },
  { name: "Comparisons", emoji: "⚖️", blurb: "Head-to-head breakdowns to help you decide." },
];

const META_BY_NAME = new Map(CATEGORY_META.map((c) => [c.name.toLowerCase(), c]));

/** Turn a category name into a stable, URL-safe slug for the ?c= filter. */
export function categorySlug(name: string): string {
  return name
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/** Metadata for a category, falling back gracefully for unknown categories. */
export function categoryMeta(name: string): HelpCategory {
  const known = META_BY_NAME.get(name.toLowerCase());
  if (known) return { ...known, slug: categorySlug(known.name) };
  return { name, slug: categorySlug(name), emoji: "📄", blurb: `Articles about ${name}.` };
}

export type HelpSection = {
  category: HelpCategory;
  posts: BlogPost[];
};

export type HelpData = {
  /** All published posts, newest first. */
  all: BlogPost[];
  /** Posts grouped into KB sections, sections ordered by CATEGORY_META then A–Z. */
  sections: HelpSection[];
  /** A small hand-off set of the newest articles for the "popular" rail. */
  popular: BlogPost[];
  /** Total number of published articles. */
  total: number;
};

/**
 * Load every published post and shape it into the help-center view model:
 * grouped sections, a "popular" rail, and totals. One DB round-trip.
 */
export async function getHelpData(): Promise<HelpData> {
  const all = await getPublishedPosts();

  const buckets = new Map<string, BlogPost[]>();
  for (const post of all) {
    const key = post.category || "Guides";
    const list = buckets.get(key);
    if (list) list.push(post);
    else buckets.set(key, [post]);
  }

  // Order: curated categories first (in CATEGORY_META order), then any extras A–Z.
  const order = new Map(CATEGORY_META.map((c, i) => [c.name.toLowerCase(), i]));
  const sections: HelpSection[] = [...buckets.entries()]
    .map(([name, posts]) => ({ category: categoryMeta(name), posts }))
    .sort((a, b) => {
      const ai = order.has(a.category.name.toLowerCase()) ? order.get(a.category.name.toLowerCase())! : 999;
      const bi = order.has(b.category.name.toLowerCase()) ? order.get(b.category.name.toLowerCase())! : 999;
      if (ai !== bi) return ai - bi;
      return a.category.name.localeCompare(b.category.name);
    });

  return {
    all,
    sections,
    popular: all.slice(0, 6),
    total: all.length,
  };
}
